(window.GIM_TS=window.GIM_TS||{})["Nazir.3"]={"from":72,"a":[["\u0003דלית ליה צירוף\u0004 \u0005[שאין לו\u0006\u0005]\u0006 צורך בהלכה זו של צירוף איסורים לשיעור, שהרי הוא מחייב על אכילת איסור כלשהו, כתוב זה \u0003\"מכל אשר יעשה\"\u0004 (במדבר ו, ד) \u0003מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא בו\u0005]?\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך: ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 הכתוב נצרך לו\u0005]\u0006 לענין זה: \u0003לעולם אינו נזיר עד שיזיר מכולן.\u0004 שלדעת ר' שמעון אם אדם נזר וקיבל על עצמו רק אחד מאיסורי הנזיר — לא חלה עליו נזירות.","\u0003אמר ר' אבהו אמר ר' אלעזר: כל רביעיות שבתורה,\u0004 כלומר, כל ההלכות שבהן יש דין לשיעור רביעית, \u0003אין היתר מצטרף לאיסור\u0004 להשלים לשיעור רביעית, \u0003חוץ מרביעית שבנזיר,\u0004 שמשקה של היתר מצטרף עם היין להתחייב עליו, \u0003שהרי אמרה תורה \"משרת\"\u0004 (\"וכל משרת ענבים לא ישתה\". במדבר ו, ג). ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל\u0005]\u0006 \u0003בין ר' יוחנן\u0004 שאמר (לעיל נזיר דף לה, ב) כל איסורים שתורה אין היתר מצטרף לאיסור חוץ מאיסורי נזיר, \u0003ל\u0004בין \u0003ר' אלעזר,\u0004 שלכאורה ניסח אותו דבר במלים אחרות?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 בענין זה, ש\u0003ר' יוחנן מרבי\u0004 \u0005[מרבה\u0006\u0005]\u0006 \u0003אפילו אוכלין,\u0004 שגם אם אכל כזית מפת וענבים הרי הוא חייב, \u0003ור' אלעזר\u0004 סבור שדווקא \u0003משקין —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 היתר מצטרף לאיסור, אבל \u0003מידי אחרינא\u0004 \u0005[דבר אחר\u0006\u0005] —\u0006 \u0003לא.\u0004","כיון שהוזכרו \"רביעיות\" מביאים מה ש\u0003אמר ר' אלעזר: עשר רביעיות הן\u0004 שנקבעו כשיעור בתחומים שונים של הלכה, \u0003ונקיט\u0004 \u0005[ואחז\u0006\u0005]\u0006 \u0003רב כהנא בידיה\u0004 \u0005[בידו\u0006\u0005]\u0006 כסימן לדבר: \u0003חמש סומקתא\u0004 \u0005[אדומות\u0006\u0005]\u0006 \u0003וחמש חיוורתא\u0004 \u0005[לבנות\u0006\u0005].\u0006 ומפרטים: \u0003חמש סומקתא\u0004 \u0005[אדומות\u0006\u0005]\u0006 של יין ודם, סימנן: \u0003\"נזיר ועושה פסח שהורו במקדש ומתו\".\u0004","ופירוטו של סימן זה: \u0003\"נזיר\"\u0004 — שיעור \u0003רביעית יין לנזיר\u0004 להתחייב מלקות על שתייתה. \u0003\"ועושה פסח\"\u0004 — ש\u0003אמר רב יהודה אמר שמואל: ארבע כוסות הללו\u0004 שמצוה לשתות בליל הסדר בפסח \u0003צריך שיהא בהן\u0004 בכל אחת מהן שיעור \u0003כדי רביעית. \"שהורו\"\u0004 הוא סימן לענין זה: מי ש\u0003שתה רביעית יין אל יורה\u0004 הוראה בדין תורה, שמא ייכשל. \u0003\"במקדש\"\u0004 — היא ההלכה שמי ש\u0003שתה רביעית יין ונכנס למקדש —\u0004 \u0003חייב מיתה.\u0004","\u0003\"ומתו\"\u0004 מהו — \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003מנין לרביעית דם שיוצאה\u0004 אף \u0003משני מתים שהיא מטמאה באהל,\u0004 שמי שנכנס לאותו אוהל או בית נטמא בטומאת המת, \u0003שנאמר\u0004 באיסור טומאה לכהנים: \u0003\"ועל כל נפשת מת לא יבא\"\u0004 (ויקרא כא, יא), שכיון שנאמר \"נפשות\" בלשון רבים, והדם הוא הנפש, מכאן שגם דם משני בני אדם מצטרף לשיעור רביעית לטמא טומאת אהל.","\u0003וחמש חיוורתא\u0004 \u0005[לבנות\u0006\u0005]\u0006 של שמן ומים, סימנן: \u0003\"חלת נזיר ומצורע שנפסלו בשבת\".\u0004 ופירוטן: \u0003\"חלת\"\u0004 — כוונתו ל\u0003רביעית שמן\u0004 שנותנים \u0003לחלה\u0004 ללחמי קרבן תודה. \u0003\"נזיר\" —\u0004 \u0003רביעית שמן לנזיר\u0004 שנותן לרקיקים שמביא בקרבנו. \u0003\"מצורע\" —\u0004 \u0003רביעית מים\u0004 חיים \u0003ל\u0004טהרת \u0003מצורע\u0004 ששוחטים את הציפור לתוכם (ראה ויקרא יד, ה). \u0003\"שנפסלו\" —\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003ושאר כל המשקין טמאין פוסלין את הגוייה,\u0004 כלומר, מי ששתה מהם פסול מלאכול תרומה, ופוסל במגעו תרומה לאכילה, אם היתה בהן \u0003רביעית.\u0004","\u0003\"בשבת\" —\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]\u0006 רשימה של הכמויות הקטנות ביותר של משקים שונים, שאם מוציא אותם בשבת מרשות אחת לרשות אחרת חייב, ובסוף שנינו: \u0003ושאר כל המשקין\u0004 שלא נתפרש שיעורם — \u0003ברביעית, ושאר כל השופכים\u0004 נוזלים ששופכים אותם — \u0003ברביעית.\u0004 הרי עשר רביעיות בהלכה.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 מעשר אין\u0005]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש\u0006\u0005]\u0006 גם הלכה זו: \u0003מרביעית נוטלין לידים ל\u0004אדם \u0003אחד ואפילו לשנים.\u0004 שרביעית מים מספיקה לנטילת ידיים לאיש אחד, ואפילו לשניים הנוטלים בבת אחת! ומשיבים: \u0003בפלוגתא לא קא מיירי\u0004 \u0005[ב\u0006דבר שיש בו מחלוקת אין הוא עוסק\u0005]\u0006 ובענין זה של נטילת ידיים רביעית לשניים יש חולקים.","ושואלים עוד: \u0003והא איכא\u0004 \u0005[והרי יש\u0006\u0005]\u0006 הלכה זו בסוטה: \u0003היה מביא פיילי\u0004 (קדירה) \u0003של חרס ונותן לתוכה חצי לוג מים מן הכיור\u0004 שבמקדש, \u0003ור' יהודה אומר: רביעית.\u0004 הרי לנו רביעית נוספת! ומשיבים: כאמור \u0003בפלוגתא לא קא מיירי\u0004 \u0005[במחלוקת איננו עוסק\u0006\u0005]\u0006 וזו היא כאמור רק דעת ר' יהודה.","ושואלים עוד: \u0003והאיכא\u0004 \u0005[והרי יש\u0006\u0005]\u0006 גם ענין זה שאמרו: \u0003כמה מים נותן לתוכה,\u0004 לכלי שיש בו מי רגליים כדי שאפשר יהיה להתפלל באותה סביבה — \u0003כל שהוא, ר' זכאי אומר: רביעית!\u0004 ומשיבים שוב: \u0003בפלוגתא לא קא מיירי\u0004 \u0005[במחלוקת איננו עוסק\u0006\u0005].\u0006 ועוד שואלים: \u0003והאיכא\u0004 \u0005[והרי יש\u0006\u0005]\u0006 \u0003מקוה,\u0004 שאמרו שרביעית מי גשמים שבקרקע אפשר לטבול בתוכה כלים קטנים מאד! ומשיבים: \u0003בר מההיא\u0004 \u0005[חוץ מזו\u0006\u0005]\u0006 ש\u0003בטלוה רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 וקבעו שלא יטבילו אפילו דברים קטנים אלא במקוה כשר של ארבעים סאה."],["עוד שנינו במשנה: \u0003ואינו חייב אלא עד שיאכל מן הענבים\u0004 שיעור \u0003כזית וכו',\u0004 ולענין שתיה, חייב על שתיית שיעור רביעית. ולדעת ר' עקיבא אף השותה שיעורו בכזית. ומסבירים את טעמיהם: ה\u0003תנא קמא\u0004 \u0005[הראשון\u0006\u0005]\u0006 \u0003לא מדמי להון\u0004 \u0005[מדמה אותם\u0006\u0005]\u0006 \u0003לכל\u0004 (את כל) \u0003איסורי נזיר ל\u0004איסור \u0003שתיה\u0004 של יין, ולכן שיעור אכילה הוא, כרגיל — בכזית, ושיעור שתיה, כרגיל — ברביעית. \u0003ור' עקיבא\u0004 סבור: \u0003כיון דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 בהמשך, בסוף הפסוק \u0003\"וענבים לחים ויבשים לא יאכל\"\u0004 (במדבר ו, ג) יש ללמוד מכך: \u0003מה אכילה כזית —\u0004 \u0003אף כל איסורין\u0004 של נזיר ב\u0003כזית.\u0004","ועוד שנינו במשנה: \u0003[וחייב על היין בפני עצמו\u0004 ועל הענבים בפני עצמן ועל החרצנים בפני עצמן\u0005].\u0006 ובאותו ענין מביאים, מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003\"וענבים לחים ויבשים לא יאכל\"\u0004 (במדבר ו, ג) — \u0003לחייב על זה בפני עצמו ועל זה בפני עצמו. מכאן אתה דן לכל איסורין שבתורה: מה כאן\u0004 בנזיר \u0003שהוא מין אחד\u0004 (\"ענבים\") \u0003והן שני שמות\u0004 (\"לחים ויבשים\") \u0003וחייב על זה בפני עצמו ועל זה בפני עצמו —\u0004 \u0003אף כל שהוא מין אחד והן שני שמות —\u0004 \u0003חייב על זה בפני עצמו ועל זה בפני עצמו.\u0004","ומסבירים מה בא הדבר ללמדנו — \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003חמרא חדתא ועינבי\u0004 \u0005[יין חדש וענבים\u0006\u0005].\u0006 שאף שלכאורה הם מין אחד, שהרי היין עדיין לא תסס והוא רק מיץ הענבים, בכל אופן חייב עליו לעצמו, משום שיש לו שם אחר.","\u0003אמר אביי:\u0004 אם \u0003אכל\u0004 הנזיר \u0003חרצן —\u0004 \u0003לוקה שתים,\u0004 פעמיים שלושים ותשע מלקות: האחת משום האיסור המפורש בחרצן, והשנית, משום האיסור \"מכל אשר ייעשה מגפן היין\". וכיוצא בדבר אם \u0003אכל זג —\u0004 \u0003לוקה שתים. אכל חרצן וזג —\u0004 \u0003לוקה שלש:\u0004 משום חרצן, משום זג, ומשום \"מכל אשר יעשה מגפן היין\". \u0003רבא אמר: אינו לוקה\u0004 אם אכל חרצן או זג \u0003אלא אחת,\u0004 ואינו לוקה על \"כל אשר יעשה מגפן היין\", משום \u0003שאינו לוקה,\u0004 כלומר, שאין לוקים על איסור \u0003לאו שבכללות,\u0004 שאם לאו אחד כולל דברים מרובים, כגון איסור זה של \"וכל אשר יעשה מגפן היין\" — אין לוקים עליו.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב פפא\u0004 על אביי ממה ששנינו, \u0003ר' אליעזר אומר: נזיר שהיה שותה יין כל היום —\u0004 \u0003אינו חייב\u0004 מלקות \u0003אלא אחת. אמרו לו\u0004 שני עדים והתרו בו: \u0003\"אל תשתה\" \"אל תשתה\" והוא שותה —\u0004 \u0003חייב על כל אחת ואחת\u0004 מההתראות והשתיה שאחריה. \u0003אכל ענבים לחים ויבשים, חרצנים וזגים, וסחט אשכול של ענבים ושתה —\u0004 \u0003לוקה חמש.\u0004 ומכאן הקושיה על דברי אביי, \u0003אי הכי\u0004 \u0005[\u0006שאם כך\u0005]\u0006 כדברי אביי — \u0003לילקי\u0004 \u0005[שילקה\u0006\u0005]\u0006 \u0003שש,\u0004 חמש אלו, ו\u0003אחת\u0004 נוספת \u0003על\u0004 שעבר על מה שנאמר \u0003\"מכל אשר יעשה\u0004 מגפן היין","\u0003\"\u0004(במדבר ו, ד)! והשיב אביי: \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 ר' אליעזר \u0003ושייר\u0004 ולא מנה כל מספר חיובי המלקות, ובאמת לוקה שש. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003שייר\u0004 עוד שאתה אומר \u0003דהאי שייר\u0004 \u0005[ששייר את זה\u0006\u0005]?\u0006 שהרי אין לומר שמנה את הכל ושייר רק אחת. ומשיבים: \u0003שייר\u0004 את הלאו הנוסף של \u0003\"לא יחל דברו\"\u0004 (במדבר ל, ג) שאף עליו הוא לוקה, שהרי עבר על נדר שנדר להימנע מכל האסור לנזיר.","ודוחים: \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003משום האי\u0004 \u0005[זה\u0006\u0005] —\u0006 \u0003לאו שיורא\u0004 \u0005[לא שיור\u0006\u0005]\u0006 \u0003הוא\u0004 זה, שכן \u0003כי קתני מידי דלא איתיה בדוכתא אחריתי\u0004 \u0005[כאשר שנה\u0006 כאן ר' אליעזר את מספר חיובי המלקות הרי זה רק דברים שאינם מצויים במקום אחר\u0005]\u0006 אלא איסורים המיוחדים לנזיר, אבל \u0003\"לא יחל דברו\" איתיה\u0004 \u0005[ישנו\u0006\u0005]\u0006 גם \u0003בנדרים\u0004 בכלל, ולכן לא הזכירו. ונמצא שהיה מן הראוי להזכיר כאן איסור \"כל אשר יעשה מגפן היין\", וקשה לאביי.","ולענין זה מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבינא מפרזקיא לרב אשי: והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003שייר\u0004 גם את \u0003בין הבינים.\u0004 שהיה יכול להוסיף עוד חיוב, שחייב לא רק על החרצן ועל הזג אלא גם על מה שבאמצע (\"מחרצנים עד זג\" — שהוא חלק הענב הנמצא בין זה וזה. ראה לעיל נזיר לד, ב)! \u0003אלא אמר רב פפא: לא תניא מידי\u0004 \u0005[נשנה\u0006 בברייתא דבר בענין\u0005]\u0006 \u0003חמש\u0004 מלקויות, אלא נאמר בה רק שלוקה על אלה, בלא פירוט כמה לוקה, ונמצא שאין להקשות מכאן על אביי. ושואלים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006"],["\u0003אותביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 ועיקר הקושיה היא ממה ששנו \u0003חמש, ומאחר\u0004 ש\u0003לא תניא\u0004 \u0005[שנויה\u0006 בברייתא\u0005]\u0006 \u0003חמש, מאי טעמא אותביה\u0004 \u0005[מה טעם הקשה לו\u0006\u0005]?\u0006 הרי אין מכאן קושיה! \u0003אמר רב פפא: אנא סברי לאו גמרא\u0004 \u0005[אני חשבתי שאין מסורת\u0006\u0005]\u0006 \u0003היא בידיה\u0004 \u0005[בידו\u0006\u0005]\u0006 של אביי שלוקה גם על \"מכל אשר יעשה מגפן היין\", \u0003והדר ביה\u0004 \u0005[ו\u0006לכן יחזור בו\u0005]\u0006 אם אביא ברייתא מפורשת נגדו, ולכן הגהתי מדעת עצמי בנוסח הברייתא, כדי לבחון מה יענה אביי. \u0003ולא ידענא דגמרא\u0004 \u0005[ולא ידעתי שמסורת\u0006\u0005]\u0006 \u0003היא בידיה\u0004 \u0005[בידו\u0006\u0005]\u0006 \u0003ו\u0004לכן \u0003לא הדר ביה\u0004 \u0005[יחזור בו\u0006\u0005].\u0006","שנינו במשנה: \u0003\"ר' אלעזר בן עזריה אומר\" כו'\u0004 ונחלקו במשנה בהגדרה מה הוא חרצן ומהו זג. \u0003אמר רב יוסף: כמאן מתרגמינן\u0004 \u0005[כ\u0006שיטת מי אנו מתרגמים\u0005]\u0006 בתרגום המקובל את הפסוק \"מחרצנים ועד זג\" \u0003מפורצנין ועד עיצורין\u0004 (מגרעינים ועד קליפות) — \u0003כ\u0004דעת \u0003ר' יוסי.\u0004","\u0003סתם נזירות\u0004 שאדם נוזר על עצמו — היא בת \u0003שלשים יום. גילח\u0004 בתוך ימי נזירותו את שערו מרצונו, \u0003או שגילחוהו לסטים\u0004 בעל כרחו — \u0003סותר\u0004 מזמן הנזירות \u0003שלשים יום\u0004 ומונה אותם מחדש. \u0003נזיר שגילח\u0004 את שערו \u0003בין\u0004 שגילח \u0003בזוג\u0004 (מספריים) \u0003בין בתער, או שסיפסף\u0004 (שיפשף) \u0003כל שהוא —\u0004 \u0003חייב.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003האי מזיא\u0004 \u0005[שיער זה\u0006\u0005]\u0006 הגדל על פני הגוף האם \u0003מלתחת\u0004 \u0005[מלמטה\u0006\u0005]\u0006 הוא \u0003רבי\u0004 \u0005[גדל\u0006\u0005]\u0006 \u0003או מלעיל\u0004 \u0005[מלמעלה\u0006\u0005]?\u0006 היכן מתווסף השיער החדש? ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006\u0005],\u0006 מה איכפת לנו להלכה אם כך או כך הוא הדבר? יש בכך משמעות \u0003ל\u0004ענין \u0003נזיר שגילחוהו ליסטים\u0004 (או הוא עצמו), ולא גילחוהו לגמרי \u0003ושיירו בו\u0004 שיער, והשיער גדול \u0003כדי לכוף\u0004 (לכופף) את \u0003ראשו לעיקרו\u0004 (לשורשו).","ואלו צדדי השאלה: \u0003אי אמרת מלתחת רבי\u0004 \u0005[אם אתה אומר ש\u0006השיער מלמטה גדל\u0005] —\u0006 את ה\u0003נזירות הא שקליה\u0004 \u0005[הרי נטל\u0006\u0005],\u0006 ששיער זה שנדר עליו שלא לגלחו, והקדישו — גילחו, שהוא הנמצא למעלה, ולכן צריך להשלים זמן הנזירות עד שיגדל שיער כראוי. \u0003אלא אי אמרת מלעיל רבי\u0004 \u0005[אם אתה אומר\u0006 שמלמעלה הוא גדל\u0005] —\u0006 \u0003מאי דאקדיש הא קאים\u0004 \u0005[מה שהקדיש הריהו קיים\u0006\u0005]\u0006 עדיין במקצתו, ודי בשיעור זה כדי לגלח עליו ולסיים נזירותו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 תשובה לדבר \u0003מהא אינבא חיה דקאים בעיקבא דבינתא\u0004 \u0005[מהכינה החיה שנמצאת\u0006 תמיד בשורש השערה\u0005]\u0006 \u0003ואי סלקא דעתך מלתחת רבי\u0004 \u0005[ואם עולה על דעתך שמלמטה גדלה\u0006 השערה\u0005] —\u0006 \u0003ברישא דבינתא בעי למיקם\u0004 \u0005[בראש השערה היתה צריכה הכינה לעמוד\u0006\u0005],\u0006 שהרי השער צומח והכינה היתה צריכה לעלות אתו. ודוחים: \u0003לעולם\u0004 תאמר כי \u0003מלתחת רבי\u0004 \u0005[מלמטה\u0006 השיער גדל\u0005]\u0006 \u0003ואגב חיותא נחית ואזיל אינבא\u0004 \u0005[ומפני חיותה הכינה יורדת והולכת\u0006\u0005],\u0006 שהיא זוחלת למטה תמיד לכיוון שורש השיער, משם היא ניזונה.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 מכך ש\u0003אינבא\u0004 \u0005[כינה\u0006\u0005]\u0006 \u0003מתה\u0004 נמצאת תמיד \u0003ברישא דבינתא\u0004 \u0005[בראש השערה\u0006\u0005],\u0006 \u0003ואי סלקא דעתך מלעיל רבי\u0004 \u0005[ואם עולה על דעתך שמלמעלה\u0006 גדל השער\u0005]\u0006 — \u0003בעיקבא דבינתא בעי למיקם\u0004 \u0005[בשורש השערה היתה צריכה לעמוד\u0006\u0005].\u0006 ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן\u0006\u0005]\u0006 אפשר לומר ש\u0003משום דלית בה חילא, שרוגי שריגא ואזיל\u0004 \u0005[שאין בה כוח, היא נתפסת\u0006 במקומה ועולה עם השיער הצומח\u0005].\u0006","ומביאים ראיה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 \u0003מבלורית\u0004 של \u0003גויים,\u0004 שמגדלים הגויים בלורית לשם עבודה זרה, וקולעים את קווצות השיער, \u0003דבתר דמגדלין לה\u0004 \u0005[שאחר שמגדלים,\u0006 קולעים אותה\u0005]\u0006 \u0003רפיא מלתחת\u0004 \u0005[נעשית רפה מלמטה\u0006\u0005],\u0006 משמע שהשיער צומח מלמטה. ודוחים: \u0003התם נמי איידי דקמטא היא משיכבא דרפיא\u0004 \u0005[שם גם כן, מתוך שהיא מתקמטת\u0006 מפני ששוכבים עליה מתרפה למטה\u0005].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה אחרת \u0003מסקרתא\u0004 \u0005[מהצבע\u0006 שצובעים בו את הכבשים\u0005],\u0006 \u0003דרפי עמרא מלתחת\u0004 \u0005[שמתרופף הצמר,\u0006 הנדבק על ידי הצבע, מלמטה\u0005]\u0006 ורואים שהשיער גדל מלמטה, ומעירים: \u0003ותניא\u0004 \u0005[ושנויה\u0006\u0005]\u0006 הלכה זו בצביעת הכבשים לצורך מעשר בהמה. \u0003ותו\u0004 \u0005[ועוד\u0006\u0005]\u0006 ראיה: \u0003כד צבעי סביא דיקנהון\u0004 \u0005[כאשר צובעים הזקנים את זקניהם\u0006\u0005]\u0006 רואים כי \u0003חוורן\u0004 \u0005[מלבינים\u0006\u0005]\u0006"],["\u0003עיקבי נימהון\u0004 \u0005[שורשי שערותיהם\u0006\u0005],\u0006 \u0003שמע מינה מלתחת רבי\u0004 \u0005[למד מכאן\u0006 שהשיער מלמטה הוא גדל\u0005]\u0006 והשיער החדש הוא שאינו צבוע. ומסכמים: אכן, כך \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005].\u0006","ומקשים: \u0003ואלא הא דתניא\u0004 \u0005[\u0006הלכה זו ששנינו בברייתא\u0005]:\u0006 \u0003נזיר שגילחוהו לסטים ושיירו בו\u0004 בגובה השער \u0003כדי\u0004 שניתן יהיה \u0003לכוף ראשו לעיקרו —\u0004 \u0003אינו סותר. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003מלתחת רבי\u0004 \u0005[מלמטה גדל\u0006 השיער\u0005],\u0006 אם כן \u0003ליסתור\u0004 \u0005[שיסתור\u0006\u0005]\u0006 גם אז, שהרי שיער זה שנותר עליו צמח רק לאחר שקיבל על עצמו נזירות! ומשיבים: מדובר \u0003כגון שגילחוהו אחר מלאת,\u0004 אחר שנשלם זמן הנזירות, אף שעדיין לא הביא את קרבנותיו. \u0003ומני\u0004 \u0005[ו\u0006כשיטת מי היא\u0005] —\u0006 שיטת \u0003ר' אליעזר היא, דאמר\u0004 \u0005[שאומר\u0006\u0005]:\u0006 \u0003כל\u0004 נזיר שנטמא \u0003אחר מלאת\u0004 רק \u0003שבעה\u0004 ימים הוא \u0003סותר.\u0004","ושואלים: לדרך זו, \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003ר' אליעזר? יליף\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 \u0003תגלחת טהרה\u0004 שבגמר הנזירות \u0003מתגלחת טומאה. מה תגלחת טומאה\u0004 אם נטמא ביום מלאת עליו להמתין \u0003שבעה\u0004 ימים, שהרי לאחר שבעה ימים נטהר מטומאת המת ומגלח שערו, \u0003אף תגלחת טהרה,\u0004 אם גילחוהו לפני הבאת קרבנותיו — סותר רק \u0003שבעה.\u0004","\u0003וקים להו לרבנן\u0004 \u0005[ומוחזק להם לחכמים\u0006\u0005]\u0006 (ובכללם ר' אליעזר) ש\u0003כל שבעה יומין\u0004 \u0005[ימים\u0006\u0005]\u0006 \u0003אתיא מזייא\u0004 \u0005[בא,\u0006 גדל, השיער\u0005]\u0006 עד \u0003כדי לכוף ראשו לעיקרו,\u0004 ולפיכך אם כשגילחוהו ביום מלאת נשתייר בו שיעור כזה של שיער — אינו סותר, ואינו חייב להמתין עוד.","שנינו במשנה: \u0003נזיר שגילח בין בתער בין בזוג או שסיפסף\u0004 (שיפשף) \u0003כל שהוא —\u0004 \u0003חייב. תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 נאמר בתורה בפרשת הנזיר: \u0003\"תער\u0004 לא יעבור על ראשו\u0003\"\u0004 (במדבר ו, ה), \u0003אין לי אלא תער\u0004 ממש, \u0003תלש\u0004 את שערו, \u0003מירט\u0004 את שערו, \u0003סיפסף כל שהוא\u0004 משערו, \u0003מנין\u0004 שאסור בו — \u0003תלמוד לומר: \"קדש יהיה גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר:\u0004 אין הדבר כן; \u0003\"תער\" —\u0004 \u0003אין לי אלא תער\u0004 בלבד, אבל אם \u0003מירט,\u0004 או \u0003תלש,\u0004 או \u0003סיפסף כל שהוא —\u0004 \u0003פטור.\u0004 ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006\u0005]\u0006 \u0003\"קדש יהיה\"!\u0004 ומשיב: \u0003למימרא\u0004 \u0005[\u0006בא הדבר לומר\u0005]\u0006 ש\u0003אם גילח ליה\u0004 \u0005[אותו,\u0006 את השיער\u0005]\u0006 \u0003בתער —\u0004 \u0003קאים עליה\u0004 \u0005[עומד,\u0006 חייב עליו\u0005]\u0006 \u0003בעשה ולא תעשה,\u0004 שעל ידי גילוח בתער עבר בכך גם על מצות העשה של \"קדוש יהיה גדל פרע שער ראשו\".","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא אחרת\u0005]:\u0006 מה שנאמר \u0003\"תער\" —\u0004 \u0003אין לי אלא\u0004 במשמעות אלא \u0003תער,\u0004 אבל אם \u0003תלש,\u0004 או \u0003מירט,\u0004 או \u0003סיפסף כל שהוא, מנין\u0004 שאסור — \u0003תלמוד לומר: \"לא יעבר על ראשו\"\u0004 (במדבר ו, ה), ללמד שאסור לו להעביר את השיער מראשו. \u0003ומאחר שסופינו לרבות כל דבר\u0004 שמעביר את השיער, \u0003מה\u0004 אם כן \u0003תלמוד לומר \"תער לא יעבר על ראשו\"?\u0004 שהרי אסור לא רק בתער!","ומסבירים: \u0003לפי שלא למדנו לתגלחת האחרונה,\u0004 תגלחת הטהרה של הנזיר \u0003שיהיה בתער\u0004 דווקא, כי בכתוב נאמר רק \"וגילח את ראשו\" ולא נתפרש כיצד מגלח. \u0003ללמדו ממצורע\u0004 שאנו יודעים שמגלח תגלחתו בתער — \u0003אי אפשר,\u0004"],["\u0003שאין דנין קל מחמור להחמיר עליו,\u0004 על הקל, וכיון שמצורע חמור יותר מנזיר, שעליו לגלח את כל שיער גופו, אי אפשר ללמוד ממנו כדי להחמיר על הנזיר, ולכן צריך שייאמר \"תער\" בנזיר ללמד שתגלחת אחרונה היא בתער דווקא.","\u0003רבי אומר: אינו צריך\u0004 את המלה \"תער\" ללמד לתגלחת אחרונה, שכן \u0003הרי הוא אומר \"תער לא יעבר על ראשו עד מלאת\u0004 הימים אשר יזיר לה'\u0003\"\u0004 (במדבר ו, ה), ומתוך הדברים נלמד כי \u0003התורה אמרה: \"אחר מלאת\" —\u0004 \u0003לא תהא תגלחת אלא בתער.\u0004","ומקשים: מדברי רבי משמע שהמלה \"תער\" מלמדת שאין איסור גילוח אלא בתער, שהרי כך הוא לומד לענין תגלחת אחרונה, \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006\u0005]\u0006 \u0003\"תער לא יעבר על ראשו\"\u0004 (במדבר ו, ה) ומ\"לא יעבור\" למדנו שאף בשאר אופנים!","ומשיבים: הרי זה בא ללמד לנזיר שגילח בתוך נזירותו בתער \u0003לעבור עליו בשני\u0004 איסורי \u0003לאוין:\u0004 משום תער, ומשום העברת שיער.","בפרטי ההלכות של גילוח השיער בנזיר \u0003אמר רב חסדא: ללקות,\u0004 אם גילח הנזיר שערו, לוקה גם \u0003ב\u0004גלל גילוח שערה \u0003אחת, לעכב\u0004 שאם גילח בסוף נזירותו את שערו והשאיר חלק מן השיער, שלא יצא ידי חובת התגלחת — הרי זה \u0003בשתים,\u0004 אם השאיר שתי שערות, \u0003לסתור\u0004 את הנזירות, אם עבר וגילח בתוך תקופת הנזירות — \u0003אינו סותר אלא\u0004 כאשר היה הגלוח \u0003ברוב ראשו ו\u0004דווקא \u0003בתער.\u0004","ושואלים: מכאן יוצא לדעת רב חסדא כי אם גילח \u0003בתער —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 הרי זה סותר, \u0003במידי אחרינא\u0004 \u0005[בדבר אחר\u0006\u0005] —\u0006 \u0003לא\u0004 סותר? \u0003והקתני\u0004 \u0005[והרי שנינו\u0006\u0005]:\u0006 \u0003מנין לרבות את כל המעבירין\u0004 את השיער שחייב עליהם — תלמוד לומר: \"לא יעבור\", בכל אופן של העברה. משמע שלא רק בתער סותר! \u0003אלא אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 כך בדברי רב חסדא: \u0003כעין תער,\u0004 שאינו סותר נזירותו אלא כשמעביר את השיער כעין תער, ולא שמשאיר את מקצתו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא גם כן כך\u0005]\u0006 כדברי רב חסדא בענין הסתירה: \u0003נזיר שתלש\u0004 משערו או \u0003מירט, סיפסף\u0004 (שיפשף) \u0003כל שהוא —\u0004 \u0003אינו סותר, אלא\u0004 כשמגלח \u0003ברוב ראשו ובתער\u0004 דווקא. \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: כשם ששתי שערות מעכבות בו\u0004 שלא תיחשב תגלחת טהרתו כתגלחת שלימה, \u0003כך\u0004 אם גילח בתוך הנזירות — \u0003שתי שערות\u0004 בלבד \u0003סותרות בו.\u0004","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה שם במסכת נגעים\u0005]:\u0006 \u0003שלשה\u0004 סוגי אנשים \u0003מגלחין, ותגלחתן\u0004 היא \u0003מצוה: נזיר, ומצורע\u0004 (\"וכבס המיטהר את בגדיו וגלח את כל שערו\"... והיה ביום השביעי יגלח את כל שערו... ויקרא יד, ח-ט) \u0003ו\u0004כלל ה\u0003לוים\u0004 בשעה שהוקדשו לראשונה (\"וכה תעשה להם לטהרם... והעבירו תער על כל בשרם\". במדבר ח, ז). \u0003וכולן שגילחו שלא בתער, או ששיירו שתי שערות —\u0004 \u0003לא עשו ולא כלום\u0004 (לא יצאו ידי חובה). ומפרשים את חלקי המשנה השונים.","\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]:\u0006 \u0003שלשה מגלחין ותגלחתן מצוה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005]\u0006 הדבר, שהרי נאמר בכולם שהם צריכים לגלח! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]\u0006 שעיקר הציווי \u0003משום עבורי\u0004 \u0005[העברת\u0006\u0005]\u0006 \u0003שער הוא\u0004 וזו היא תכלית המצוה, \u0003ו\u0004לכן \u0003אפילו סך\u0004 את שערו \u0003נשא\u0004 (סם המשיר את השער) יצא, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 ש\u0003לא\u0004 כך הדבר, אלא המצוה היא בתגלחת.","\u0003קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 שם עוד: \u0003וכולן שגילחו שלא בתער\u0004 — לא יצאו. ושואלים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר\u0004 מובן הדבר, שכן \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 בו: \u0003\"תער לא יעבר על ראשו\",\u0004 ולמדנו מכאן שאף מצוות תגלחתו בתער. \u0003ו\u0004כן \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003לוים\u0004 גם כן \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]:\u0006 \u0003\"והעבירו תער על כל בשרם\"\u0004 (במדבר ח, ז). \u0003אלא מצורע\u0004 שתגלחת טהרתו \u0003בתער\u0004 דווקא, \u0003מנלן\u0004 \u0005[מניין לנו\u0006\u0005]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר\u0006\u0005]:\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מ\u0004ה\u0003לוים\u0004 בדרך זו: \u0003מה לוים שכן טעונין\u0004 (חייבים) \u0003תגלחת, ואין תגלחתן אלא בתער —\u0004 \u0003אף אני אביא את המצורע שהוא טעון תגלחת —\u0004 \u0003ואין תגלחתו אלא בתער.\u0004 אולם \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום לשבור, להקשות\u0005]\u0006 את ההשוואה הזו ולומר: \u0003מה ללוים —\u0004 \u0003שכן\u0004 יש בהם חומרה יתירה ש\u0003טעונין תנופה בגופם,\u0004 שהרי בהקדשתם היה צריך אהרן גם להניף אותם עצמם (במדבר ח, יא), \u0003תאמר במצורע\u0004 ש\u0003לא\u0004 טעון תנופה!","\u0003אלא\u0004 מה תאמר ש\u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 ההלכה שתגלחת מצורע דווקא בתער מתוך השוואה ל\u0003נזיר,\u0004 שאף הוא אינו טעון תנופה. ואולם גם את ההשוואה הזו אפשר לדחות: \u0003מה לנזיר\u0004 שיש בו חומרה יתירה — \u0003שכן קרבנו טעון לחם, תאמר במצורע\u0004 ש\u0003לא. אלא\u0004 צריך לומר שהלכה זו במצורע \u0003מחדא\u0004 \u0005[מ\u0006הלכה אחת\u0005]\u0006 כגון לויים או נזיר \u0003לא אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005],\u0006 \u0003תיתי מתרויהון\u0004 \u0005[תבוא,\u0006 תילמד משתיהן\u0005].\u0006","שכן, כפי שאמרנו \u0003מהי תיתי\u0004 \u0005[מאיזו תבוא,\u0006 תילמד\u0005]?\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 \u0003מלוים\u0004 — הרי יש לפרוך: \u0003מה ללוים —\u0004 \u0003שכן טעונין תנופה בגופן.\u0004 אולם אז אפשר לטעון כנגד הפירכה הזו: \u0003נזיר יוכיח,\u0004 שלא זו החומרה היא הגורמת לדין גילוח בתער, שהרי נזיר אינו טעון תנופה בגופו, ומכל מקום צריך לגלח בתער. ואם תטען כנגד זה: \u0003מה לנזיר שכן קרבנו טעון לחם\u0004 — הרי אפשר לדחות: \u0003לוים יוכיחו\u0004 שלא חומרה זו היא הגורמת לדין גילוח בתער, שהרי לויים אינם טעונים לחם בקרבנם ובכל זאת צריכים לגלח בתער.","\u0003וחזר\u0004 (סובב) \u0003הדין\u0004 (לימוד זה) מכאן לכאן, \u0003לא ראי זה כראי זה, ולא ראי זה כראי זה,\u0004 שהרי אפשר להראות הבדלים בין כל פרט ממנו אנו רוצים ללמוד. \u0003הצד השוה שבהם —\u0004 \u0003שהן טעונין תגלחת, ותגלחתן בתער. אף אני אביא את המצורע שהוא טעון תגלחת —\u0004 \u0003ותגלחתו\u0004 אף היא אינה אלא \u0003בתער.\u0004","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבא מברניש לרב אשי: ולפרוך\u0004 \u0005[ושישבור\u0006\u0005]\u0006 לימוד זה באופן הבא: \u0003מה להצד השוה שבהן\u0004 בלויים ובנזיר, \u0003שכן\u0004"],["\u0003אין קרבנו בדלות,\u0004 שבכל אחד מאלה יש קרבן קצוב ואין פוחתים ממנו בגלל דלותו של החייב בקרבן, \u0003תאמר במצורע שקרבנו\u0004 בא גם \u0003בדלות,\u0004 שאם דל הוא מביא תורים במקום כבשים (ויקרא יד, כא-כב). וכיון שמצאנו שהיקל בו הכתוב בהשוואה לנזיר ולווים, שמא היקל בו גם לענין גילוח, שלא להצריכו דווקא תער! ואם כן אין מקור להוכיח שתגלחת במצורע היא בתער דווקא.","בהמשך לדיונים אלה \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבא בר משרשיא לרבא: האי תנא\u0004 \u0005[תנא זה\u0006\u0005],\u0006 \u0003מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 \u0003אמר\u0004 לענין נזיר שתגלחתו בתער (לעיל נזיר לט, ב): \u0003ללמדו ממצורע אי אפשר,\u0004 משום \u0003שאין דנין קל מחמור להחמיר עליו,\u0004 ומכאן משמע שפשוט לו הדבר שתגלחת מצורע עצמו היא בתער. \u0003והדר\u0004 \u0005[וחזר\u0006\u0005]\u0006 ו\u0003אמר\u0004 ש\u0003נילף מדינא\u0004 \u0005[נלמד מן הדין\u0006\u0005]\u0006 בבנין אב שתגלחת מצורע היא בתער דווקא, \u0003ו\u0004לבסוף \u0003מדינא נמי\u0004 \u0005[מן הדין גם כן\u0006\u0005]\u0006 \u0003לא יליף\u0004 \u0005[למד\u0006\u0005]\u0006 כפי הפירכה של רבא מברניש. ואם כן מה מקור ההלכה הזו במצורע?","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003ההוא\u0004 \u0005[אותה\u0006\u0005]\u0006 ברייתא שאמרה שאין ללמוד ממצורע, ומשמע ממנה שפשוט שמצורע מגלח בתער, היא \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים\u0006\u0005]\u0006 הלמדים תגלחת מצורע מאיסור השחתת זקן. \u0003הא\u0004 \u0005[זה\u0006\u0005] —\u0006 \u0003אליבא\u0004 \u0005[על פי שיטת\u0006\u0005]\u0006 \u0003ר' אליעזר\u0004 שאינו למד תגלחת מצורע מאיסור השחתת זקן, ולפיכך נזקק הוא ללמוד דבר זה מן הדין. \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003ו\u0004כל אדם \u0003אינו חייב\u0004 על השחתת זקנו \u0003עד שילקטנו\u0004 (יטלנו, יגלחנו) \u0003בתער. ר' אליעזר אומר: אפילו ליקטו במלקט\u0004 (מלקחיים קטנים), או \u0003ברהיטני\u0004 (מעין מקצוע) — \u0003חייב.\u0004 שאינו סבור שאיסור השחתת זקן הוא בתער דווקא.","ומסבירים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים\u0006\u0005],\u0006 כיצד למדים הם מכאן שתגלחת מצורע צריכה להיות בתער דווקא? — \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בתגלחת המצורע \"יגלח את כל שערו את ראשו ואת זקנו\" (ויקרא יד, ט) וכיון שנאמר תחילה \"כל שערו\", \u0003\"זקנו\" מה תלמוד לומר?\u0004 אלא \u0003לפי שנאמר\u0004 בכהנים \u0003\"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה) \u0003יכול אפילו מצורע כן,\u0004 שאם היה כהן מצורע ובא להתגלח, שיהא אסור לו לגלח את זקנו — \u0003תלמוד לומר: \"זקנו\".\u0004 שחזר הכתוב והדגיש, שלמרות האיסור הכללי בכהן לגלח זקן, בכל זאת חייב המצורע לגלחו.","\u0003ומנלן\u0004 \u0005[ומנין לנו\u0006\u0005]\u0006 שגילוח זה שלמדנו ממנו למצורע הוא דווקא \u0003בתער —\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]\u0006 לגבי איסור גילוח הזקן לכהנים: \u0003\"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה), \u0003יכול אפילו גילחו\u0004 את הזקן \u0003במספרים יהא חייב —\u0004 \u0003תלמוד לומר\u0004 באיסור הכללי לכל ישראל: \u0003\"ולא תשחית\u0004 את פאת זקנך\u0003\"\u0004(ויקרא יט, כז), ללמד שאין חייב אלא בדרך השחתה, כשמשחית את זקנו עד שרשיו, מה שאין כן במספריים.","\u0003יכול ליקטו במלקט וברהיטני\u0004 שיש בו השחתה \u0003יהא חייב —\u0004 \u0003תלמוד לומר: \"ופאת זקנם לא יגלחו\",\u0004 שאין חייב על השחתת זקן אלא בדרך גילוח. \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003כיצד? איזהו\u0004 האופן של \u0003גילוח שיש בו השחתה —\u0004 \u0003הוי אומר זה תער.\u0004 ומכאן למדים חכמים לתגלחת מצורע, שמה שנאסר בכהן — בתער, מצוה לעשותו בתגלחת המצורע.","ומקשים: \u0003ממאי\u0004 \u0005[ממה\u0006\u0005]\u0006 אתה מסיק שמצות גילוח במצורע היא דווקא בתער? \u0003דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003לעולם\u0004 תאמר \u0003אפילו ליקטו במלקט\u0004 או \u0003ברהיטני נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003מצוה קעביד\u0004 \u0005[\u0006הוא עושה\u0005]\u0006 ויוצא ידי חובה, \u0003והא קאתי לאשמועינן\u0004 \u0005[ו\u0006דבר זה בא להשמיענו\u0005]\u0006 ש\u0003אפילו\u0004 גילח \u0003בתער לא מיחייב עליה\u0004 \u0005[אינו חייב עליו\u0006\u0005]\u0006 משום השחתה. אבל אין מכאן הוכחה שחובת הגילוח היא בתער דווקא!","\u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]\u0006 כתשובה לזה: \u0003אי סלקא דעתך כי עביד נמי\u0004 \u0005[אם עולה על דעתך שכאשר עושה גם כן\u0006\u0005]\u0006 \u0003במלקט\u0004 או \u0003ברהיטני שפיר דמי\u0004 \u0005[יפה הדבר\u0006\u0005],\u0006 אם כן \u0003לישתוק קרא מיניה\u0004 \u0005[שישתוק הכתוב ממנו\u0006 מן הייתור של \"זקנו\"\u0005]\u0006 ולא יאמר דבר בענין זה, \u0003ואנא אמינא\u0004 \u0005[ואני\u0006 מעצמי אומר כך\u0005]:\u0006 \u0003ומה גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר דאיסורא קא עביד\u0004 \u0005[שאיסור הוא\u0006 עושה\u0005]\u0006 כאשר מגלח את שערו בתוך ימי הנזירות, \u0003אפילו הכי\u0004 \u0005[כך\u0006\u0005]\u0006 הוא \u0003מחייב\u0004 \u0005[מתחייב\u0006\u0005]\u0006 גם על העברת שיער שלא בתער, \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 במצורע ש\u0003מצוה\u0004 היא, \u0003כל שכן\u0004 שיהיה מותר לגלח בכל דבר?"],["\u0003ותו,\u0004 \u0003אי סלקא דעתך\u0004 \u0005[ועוד, אם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003כי עביד\u0004 \u0005[כאשר עושה\u0006\u0005]\u0006 תגלחת \u0003במלקט,\u0004 או \u0003ברהיטני מצוה קא עביד\u0004 \u0005[הוא\u0006 עושה\u0005]\u0006 \u0003מ\u0004כיון ש\u0003לא כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 \u0003\"תער\"\u0004 היה מקום לומר כאן שאינו רשאי כלל לגלח בתער, \u0003כריש לקיש,\u0004 ש\u0003אמר\u0004 כלל:","\u0003כל מקום שאתה מוצא\u0004 מצות \u0003עשה ו\u0004מצות \u0003לא תעשה\u0004 שיש ניגוד ביניהן, \u0003אם אתה יכול\u0004 למצוא דרך \u0003לקיים את שניהם —\u0004 \u0003מוטב, ואם לאו\u0004 \u0005[לא\u0006\u0005] —\u0006 \u0003יבא עשה וידחה את לא תעשה,\u0004 ואף כאן, הרי יכול המצורע לקיים את מצות תגלחתו במלקט או ברהיטני, ואין מקום להתיר לו תגלחת בתער שהיא בלא תעשה. אלא מאחר שהוצרך הכתוב לומר שעשה זה של תגלחת מצורע דוחה את מצות לא תעשה של השחתת זקן, מוכח שאין מצוות גילוח אלא בתער בלבד.","ומסבירים: \u0003ור' אליעזר מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 דבריו, מניין הוא יודע שתגלחת מצורע בתער? — \u0003יליף\u0004 \u0005[לומד\u0006\u0005]\u0006 הוא את הדבר \u0003מ\u0004מה שנאמר בתגלחת המצורע \"יגלח את כל שערו... את \u0003ראשו\u0004 ואת זקנו...\" (ויקרא יד, ט). \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003\"ראשו\" מה תלמוד לומר?\u0004 שהרי כבר נאמר \"כל שערו\"! \u0003לפי שנאמר גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר \"תער לא יעבר על ראשו\"\u0004 (במדבר ו, ה), \u0003יכול אף נזיר מצורע כן,\u0004 שבזמן טהרתו מן הצרעת אסור יהיה לו לגלח את ראשו משום נזירותו — \u0003תלמוד לומר: \"ראשו\",\u0004 שאף הוא צריך לגלח ראשו בתער.","ודוחים: \u0003ממאי\u0004 \u0005[ממה\u0006\u0005]\u0006 מסיק אתה שכך הוא? \u0003דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003לעולם\u0004 תאמר \u0003אפילו ליקטו\u0004 המצורע \u0003במלקט\u0004 או \u0003ברהיטני —\u0004 \u0003מצוה\u0004 \u0003קעביד\u0004 \u0005[הוא עושה\u0006\u0005].\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר\u0006\u0005]:\u0006 \u0003תער למה לי,\u0004 כלומר, מה למדנו מגזירה שווה של \"ראשו\" לענין תער — יש לפרש כי בא \u0003למימרא\u0004 \u0005[לומר\u0006\u0005]\u0006 ש\u0003אפילו בתער\u0004 מותר. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר\u0006\u0005]\u0006 \u0003הואיל וגבי\u0004 \u0005[ואצל\u0006\u0005]\u0006 \u0003נזיר כי עביד\u0004 \u0005[כאשר\u0006 הוא עושה\u0005]\u0006 תגלחת \u0003בתער, מיחייב\u0004 \u0005[\u0006הוא מתחייב\u0005]\u0006 מלקות על האיסור, ואם כן \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003מצורע נמי ליחייב\u0004 \u0005[גם כן שיתחייב\u0006\u0005]\u0006 הנזיר מלקות גם אם גילח לצרעתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 ש\u0003לא!\u0004","ומשיבים: \u0003אי סלקא דעתך כי עביד\u0004 \u0005[אם עולה על דעתך\u0006 לומר שכאשר המצורע עושה תגלחתו\u0005]\u0006 \u0003במלקט\u0004 או \u0003ברהיטני מצוה קעביד\u0004 \u0005[\u0006הוא עושה\u0005]\u0006 הרי \u0003מ\u0004פני ש\u0003לא כתב\u0004 \u0005[כתוב\u0006\u0005]\u0006 במפורש \u0003\"תער\"\u0004 אסור היה לגלח בתער, \u0003כ\u0004דברי \u0003ריש לקיש\u0004 שאמרנו, שבמקרה שיכול לקיים את המצוה בלא לעבור על איסור אינו רשאי לעבור עליו, אלא בוודאי בא הכתוב לומר שמצות התגלחת היא דווקא בתער.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 \u0003האי\u0004 \u0005[\u0006פסוק זה\u0005]\u0006 שנאמר במצורע \u0003\"ראשו\", מאי דרשי ביה\u0004 \u0005[מה\u0006 הם דורשים בו?\u0005]\u0006 ומשיבים: \u0003מיבעי להו\u0004 \u0005[צריכים הם\u0006\u0005]\u0006 את ההדגשה הזו כדי \u0003למידחי\u0004 \u0005[לדחות\u0006\u0005]\u0006 את ה\u0003לאו\u0004 (מצות לא תעשה) של \u0003הקפה\u0004 של פאות הראש. וכפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"לא תקיפו פאת ראשכם\"\u0004 (ויקרא יט, כז), \u0003יכול אף מצורע כן\u0004 שאסור בכך בשעת תגלחתו — \u0003תלמוד לומר\u0004 במצורע במפורש: \u0003\"ראשו\".\u0004","ושואלים: \u0003למה לי למכתב\u0004 \u0005[לכתוב\u0006\u0005]\u0006 \u0003\"ראשו\"? ותיפוק ליה\u0004 \u0005[ותצא,\u0006 תילמד, לו\u0005]\u0006 ההלכה הזו שמצות גילוח דוחה את האיסור מ\u0003\"זקנו\"\u0004 (ויקרא יד, ט). \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003\"זקנו\"\u0004 (ויקרא יד, ט) \u0003מה תלמוד לומר? לפי שנאמר\u0004 בכהנים \u0003\"ופאת זקנם לא יגלחו\"\u0004 (ויקרא כא, ה), \u0003יכול אף מצורע כן\u0004 שאסור בתגלחת הזקן — \u0003תלמוד לומר: \"זקנו\".\u0004","ואם כן \u0003למה לי למכתב\u0004 \u0005[לכתוב\u0006\u0005]\u0006 \u0003\"ראשו\" ולמה לי למכתב \"זקנו\"?\u0004 שהרי מאחד מהם אפשר ללמוד שתגלחת מצורע דוחה מצוות לא תעשה אחרות שיש בכך! ומשיבים: \u0003צריכי\u0004 \u0005[צריכים\u0006\u0005]\u0006 שני הכתובים להיאמר, משום \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה\u0006\u0005]\u0006 \u0003\"זקנו\"\u0004 בלבד \u0003ולא כתב\u0004 \u0005[היתה כותבת\u0006\u0005]\u0006 \u0003\"ראשו\", הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003הקפת כל הראש\u0004 שאם מגלח את כל שיער הראש כולו, ולא רק את שיער הצדעיים, תגלחת כזו \u0003לא שמה\u0004 (אינה נקראת) \u0003הקפה\u0004 אסורה, ולכן אין איסור תורה בתגלחת המצורע שמגלח את כל שיער ראשו. \u0003להכי כתב רחמנא\u0004 \u0005[\u0006לשם כך כתבה התורה\u0005]\u0006 \u0003\"ראשו\"\u0004 ללמד מכאן לענין הקפה, שאף שמה שעושה המצורע הוא בעצם עבירה על דין הקפה, התורה ציוותה עליו לעשות זאת."],["\u0003ואי כתב\u0004 \u0005[ואם היתה\u0006 התורה כותבת\u0005]\u0006 \u0003\"ראשו\"\u0004 בלבד \u0003ולא כתב\u0004 \u0005[היתה כותבת\u0006\u0005]\u0006 גם \u0003\"זקנו\", הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 אמנם \u0003משמע\u0004 כאן \u0003תרתי\u0004 \u0005[שני\u0006 דברים\u0005]:\u0006 גם \u0003דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 ציווי \u0003עשה ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 \u0003את לא תעשה, ומשמע\u0004 מכאן גם ש\u0003הקפת כל הראש שמה הקפה. ואכתי\u0004 \u0005[ועדיין\u0006\u0005]\u0006 שתהא מצוות גילוח מצורע \u0003בתער מנלן\u0004 \u0005[מניין לנו\u0006\u0005]?\u0006 \u0003להכי כתב רחמנא\u0004 \u0005[ל\u0006שם כך כתבה תורה\u0005]\u0006 גם \u0003\"זקנו\",\u0004 ולמדנו מאיסור השחתת זקן בכהנים שהכוונה לתער.","ושואלים: \u0003ור' אליעזר,\u0004 הדין הכללי \u0003דאתי\u0004 \u0005[שבא\u0006\u0005]\u0006 ציווי \u0003עשה ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 \u0003את לא תעשה מנליה\u0004 \u0005[מנין לו\u0006\u0005]?\u0006 ומשיבים: \u0003יליף\u0004 \u0005[לומד\u0006\u0005]\u0006 הוא דבר זה \u0003מגדילים\u0004 של ציצית. \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 אף שנאמר \u0003\"לא תלבש שעטנז\"\u0004 (דברים כב, יא),"],["\u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003\"גדילים תעשה לך\"\u0004 (דברים כב, יב) \u0003מהם,\u0004 מצמר ופשתים, שסמכה התורה לאיסור שעטנז את מצות ציצית, ללמד שמצות עשה של ציצית שיש בה תכלת של צמר דוחה את איסור שעטנז, ומותר להטיל ציצית צמר בבגד פשתים. ומכאן למדים הלכה כללית, שמצות עשה דוחה את מצות לא תעשה.","ושבים לדון בפרטי המשנה שהובאה לעיל (נזיר מ, א). \u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]:\u0006 \u0003וכולם,\u0004 נזיר, מצורע ולויים \u0003שגילחו\u0004 את שערם \u0003שלא בתער, או ששיירו שתי שערות —\u0004 \u0003לא עשו ולא כלום. אמר רב אחא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב איקא: זאת אומרת,\u0004 מכאן נסיק שהכלל האומר ש\u0003רובו\u0004 של דבר נחשב \u0003ככולו —\u0004 \u0003מדאורייתא\u0004 \u0005[מן התורה\u0006\u0005]\u0006 הוא.","\u0003ממאי\u0004 \u0005[ממה\u0006\u0005]\u0006 אנחנו למדים זאת — \u0003מדגלי רחמנא\u0004 \u0005[מ\u0006תוך שגילתה ופירשה התורה\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר \"ביום השביעי יגלחנו\"\u0004 (במדבר ו, ט) וכבר נאמר קודם לכן \"וגילח ראשו ביום טהרתו\" — הדגשה זו מלמדת כי דווקא \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 \u0003הוא\u0004 הדין שאינו מקיים מצות הגילוח \u0003עד דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003כולו\u0004 ואין מסתפקים בגילוח רובו. \u0003הא בעלמא\u0004 \u0005[הרי בסתם\u0006\u0005],\u0006 בשאר דיני התורה, אומרים אנו: \u0003רובו ככולו.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך\u0006\u0005]\u0006 \u0003ר' יוסי בר' חנינא:\u0004 הלא \u0003האי\u0004 \u0005[\u0006פסוק זה\u0005]\u0006 \"ביום השביעי יגלחנו\" \u0003בנזיר טמא כתיב\u0004 \u0005[נאמר\u0006\u0005],\u0006 ולא בטהור, והמשנה אינה מחלקת בדבר, ואף נזיר טהור בכלל, ואם כן לא ניתן לדייק מכאן דיוק זה! \u0003מחכו עלה במערבא\u0004 \u0005[צחקו עליה,\u0006 על קושיה זו, בארץ ישראל\u0005]:\u0006 \u0003מכדי\u0004 \u0005[הרי\u0006\u0005]\u0006 כל עיקרו של דין \u0003נזיר טמא\u0004 שמגלח תגלחת מצוה דווקא \u0003בתער מנלן\u0004 \u0005[מניין לנו\u0006\u0005] —\u0006 \u0003מנזיר טהור יליף\u0004 \u0005[למד\u0006\u0005],\u0006 אם כן \u0003ליתי\u0004 \u0005[יבוא\u0006\u0005]\u0006 \u0003נזיר טהור ולילף\u0004 \u0005[וילמד\u0006\u0005]\u0006 \u0003מנזיר טמא\u0004 לענייננו: \u0003מה\u0004 נזיר \u0003טמא כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 \u0003שייר שתי שערות —\u0004 \u0003ולא כלום עבד\u0004 \u0005[עשה\u0006\u0005],\u0006 שאין הדבר נחשב לו לתגלחת, \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005],\u0006 בנזיר טהור, \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 \u0003שייר שתי שערות ולא כלום עבד\u0004 \u0005[עשה\u0006\u0005].\u0006","ובאותו ענין \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003אביי: נזיר שגילח\u0004 והניח \u0003שתי שערות,\u0004 שאמרנו שאין תגלחת זו עולה לו, אם \u0003צמח ראשו\u0004 (שערו) \u0003וחזר וגילחן\u0004 את שתי השערות הללו בלבד, \u0003מהו? מי מעכבי\u0004 \u0005[האם\u0006 הן מעכבות\u0005]\u0006 \u0003או לא\u0004 מעכבות, האם אפשר לומר שבגילוח זה השלים את תגלחתו הראשונה, או שמא עתה בזמן שראשו מלא שיער אין תגלחת שתי שערות נחשבת, וצריך לגלח את כל שיער ראשו?","וכן \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רבא: נזיר שגילח והניח שתי שערות, ו\u0004אחר כך \u0003גילח אחת\u0004 מהן \u0003ונשרה אחת\u0004 מהן מעצמה, \u0003מהו?\u0004 האם נחשב הדבר כגילוח כל הראש, או לא? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב אחא מדיפתי לרבינא:\u0004 וכי השאלה אם \u0003גילח\u0004 את שערו \u0003שערה שערה קא מיבעי ליה\u0004 \u0005[נשאלת לו\u0006\u0005]\u0006 \u0003לרבא?\u0004 מדוע יהא שונה מקרה זה ממקרה בו היה מגלח את כל שערותיו שערה שערה? והרי השערה שנותרה ונשרה מעצמה אחרי כן אינה מעכבת!","\u0003אלא\u0004 יש לשנות את נוסח השאלה \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 כך: \u0003נשרה אחת וגילח אחת, מהו\u0004 מה יהיה הדין, האם קיים מצות גילוח? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 במקרה זה \u0003גילוח אין כאן, שער אין כאן.\u0004 על לשון זו תוהים: \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003שער אין כאן\u0004 — אם כן \u0003גילוח יש כאן,\u0004 כיון שלא נשאר שיער! ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006\u0005]:\u0006 \u0003אף על פי ששער אין כאן,\u0004 שהרי נותרה רק שערה אחת, מכל מקום \u0003מצות גילוח אין כאן,\u0004 שהרי בתגלחת ראשונה לא גילח הכל, ובפעם השניה לא גילח כשיעור.","\u0003נזיר חופף\u0004 את ראשו \u0003ומפספס\u0004 מבדיל ומחליק את השערות בידיים, ואינו צריך לחשוש שמא מתוך כך ינשור שערו, \u0003אבל לא סורק.\u0004","ומבררים: מה ששנינו במשנתנו כי נזיר \u0003חופף ומפספס, מני\u0004 \u0005[\u0006שיטת מי היא\u0005]\u0006 שמתיר? — שיטת \u0003ר' שמעון היא, דאמר\u0004 \u0005[שאומר\u0006\u0005]:\u0006 \u0003דבר שאין מתכוין מותר.\u0004 ומשום כך אף אם על ידי כך נושרות שערות, הואיל ואין כוונתו לכך — מותר הדבר. ואולם בהמשך המשנה \u0003אבל לא סורק —\u0004 \u0003אתאן לרבנן\u0004 \u0005[באנו ל\u0006שיטת חכמים\u0005],\u0006 שהרי גם בסריקה איננו מתכוון להשיר את השיער, ובכל זאת אמרו שאסור.","ואם כן תמוהה המשנה, וכי \u0003רישא\u0004 \u0005[תחילתה\u0006\u0005]\u0006 כשיטת \u0003ר' שמעון וסיפא\u0004 \u0005[וסופה\u0006\u0005]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 החולקים על ר' שמעון? \u0003אמר רבה:\u0004 כל המשנה \u0003כולה,\u0004 שיטת \u0003ר' שמעון היא,\u0004 ודעתו היא ש\u0003כל הסורק —\u0004 \u0003להסיר נימין\u0004 (שערות) \u0003מדולדלות\u0004 הוא \u0003מתכוין,\u0004 ואם כן יש לראות בכך דבר שעושה במתכוון.","\u0003ר' ישמעאל אומר: לא יחוף\u0004 (יחפוף) הנזיר את ראשו \u0003באדמה, מפני שמשרת את השער.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 מה בדיוק לשון המשנה, האם \u0003\"מפני שהיא משרת את השער\" תנן\u0004 \u0005[שנינו\u0006\u0005],\u0006 שסתם אדמה משירה שיער, \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003\"מפני המשרת\" תנן\u0004 \u0005[שנינו\u0006\u0005]?\u0006 שאמנם יש סוגי אדמה שאין משירים שיער, ובכל זאת אסרום מפני אותם המשירים שיער. ומבררים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006\u0005]\u0006 אם כך או כך הגירסה?","\u0003כגון דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 מין \u0003אדמה\u0004 ש\u0003לא מתרא\u0004 \u0005[משרת\u0006\u0005]\u0006 שיער; \u0003אי אמרת\u0004 \u0005[אם אתה אומר\u0006\u0005]\u0006 \u0003\"מפני שהיא משרת\" תנן\u0004 \u0005[שנינו\u0006\u0005]\u0006 נמצא כי \u0003היכא דידעינן דלא מתרא\u0004 \u0005[היכן שאנו יודעים שאיננה משרת\u0006\u0005] —\u0006 \u0003שפיר\u0004 \u0005[יפה,\u0006 טוב הדבר\u0005]\u0006 ומותר לחפוף. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר\u0006\u0005]\u0006 בנוסח \u0003\"מפני המשרת\"\u0004 המשמעות היא שגזרו על כל אדמה, מפני אותו סוג אדמה שמשיר את השיער, ולכן אף באדמה אחרת שאינה משירה שיער — \u0003כלל כלל לא.\u0004 לשאלה זו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 השאלה במקומה.","\u0003נזיר שהיה שותה יין כל היום —\u0004 \u0003אינו חייב אלא אחת. אמרו לו\u0004 במשך היום: \u0003\"אל תשתה\", \"אל תשתה\", והוא שותה —\u0004 \u0003חייב על כל אחת ואחת\u0004 שהתרו בו. וכן נזיר רגיל ש\u0003היה מגלח כל היום —\u0004 \u0003אינו חייב אלא אחת. אמרו לו: \"אל תגלח\", \"אל תגלח\", והוא מגלח —\u0004 \u0003חייב על כל אחת ואחת.\u0004 וכן אם \u0003היה מטמא למתים כל היום —\u0004 \u0003אינו חייב אלא אחת. אמרו לו: \"אל תטמא\" \"אל תטמא\", והוא מטמא —\u0004 \u0003חייב על כל אחת ואחת.\u0004"],["איתמר \u0005[נאמר\u0006\u0005]\u0006 שנחלקו אמוראים בענין הבא, \u0003אמר רבה אמר רב הונא: מקרא מלא דבר הכתוב\u0004 בדין הנזיר \u0003\"לא יטמא\u0004 להם במותם\u0003\"\u0004 (במדבר ו, ז) ובכלל זה כל מיני טומאות המת (מגע, משא, אוהל), \u0003כשהוא,\u0004 הכתוב, \u0003אומר\u0004 \u0003\"\u0004על נפש מת \u0003לא יבא\"\u0004 (במדבר ו, ו) — הרי פסוק נוסף זה בא \u0003להזהירו על הטומאה, להזהירו על הביאה\u0004 לבית (\"אוהל\") בו נמצא המת, אזהרה נוספת בפני עצמה, שעובר על כל אחת מהן בפני עצמה. \u0003אבל טומאה וטומאה\u0004 אם חזר ונטמא — \u0003לא.\u0004","\u0003ורב יוסף אמר\u0004 בלשון שבועה: \u0003האלהים!\u0004 כך \u0003אמר רב הונא: אפילו טומאה וטומאה\u0004 חייב על שתיהן. ומביא ראיה לדבריו ממה ש\u0003אמר רב הונא: נזיר שהיה עומד בבית הקברות\u0004 וממילא הוא טמא, \u0003והושיטו לו מתו\u0004 (אחד מקרוביו שמת) \u0003ו\u0004כן אם הושיטו לו \u0003מת אחר ונגע בו —\u0004 \u0003חייב.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 הוא חייב? \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 הוא \u0003מיטמא וקאים\u0004 \u0005[ועומד\u0006\u0005]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן\u0006\u0005]\u0006 ש\u0003אמר רב הונא\u0004 שהוא עובר \u0003אפילו\u0004 משום \u0003טומאה וטומאה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003אביי\u0004 לרב יוסף ממה ששנינו בברייתא: \u0003כהן שהיה לו מת מונח על כתיפו, והושיטו לו מתו ומת אחר ונגע בו, יכול יהא חייב\u0004 אף על נגיעה זו — \u0003תלמוד לומר\u0004 בקשר לאיסור טומאה בכהן גדול: \u0003\"ולא יחלל\u0004 את מקדש אלהיו\u0003\"\u0004 (ויקרא כא, יב) ומכאן שנאמר איסור טומאה \u0003במי ש\u0004עדיין \u0003אינו מחולל, יצא\u0004 (למעט) \u0003זה שהוא\u0004 כבר \u0003מחולל\u0004 (טמא) \u0003ועומד,\u0004 שאינו מוזהר על כך.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 רב יוסף: אם כן שאתה סבור שאינו מוזהר על טומאה לאחר טומאה \u0003ותיקשי\u0004 \u0005[ותיקשה\u0006\u0005]\u0006 \u0003לך מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003היה מיטמא למתים כל היום —\u0004 \u0003אינו חייב אלא אחת. אמרו לו \"אל תטמא\" \"אל תטמא\" —\u0004 \u0003חייב על כל אחת ואחת. ואמאי\u0004 \u0005[ומדוע\u0006\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 הוא \u0003מיטמא וקאים\u0004 \u0005[ועומד\u0006\u0005]!\u0006","\u0003אלא קשיא אהדדי\u0004 \u0005[קשים\u0006 הדברים זה על זה\u0005]\u0006 דברי המשנה ודברי הברייתא! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה קשה\u0005];\u0006 \u0003כאן\u0004 בברייתא — מדובר \u0003בחיבורין,\u0004 שכאשר היה נוגע במת, תוך כדי כך נגע במת אחר, ואז אין הוא מתחייב על הטומאה השניה. \u0003כאן,\u0004 במשנה — מדובר \u0003שלא בחיבורין,\u0004 שאחר שנגע במת אחד והניחו — נגע במת השני, ואז חייב על הנגיעה החדשה לעצמה.","ושואלים: \u0003ו\u0004דין זה של \u0003טומאה בחיבורין\u0004 שכל עוד הוא נוגע במת הוא נחשב כמחובר לטומאה, האם \u0003דאורייתא\u0004 \u0005[מן התורה\u0006\u0005]\u0006 הוא עד שאינו לוקה על הטומאה השנית משום כך? \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אמר \u0003רב יצחק בר יוסף אמר ר' ינאי: לא אמרו\u0004 כלל זה שיש \u0003טומאה בחיבורין אלא ל\u0004ענין אכילת \u0003תרומה וקדשים,\u0004 שהנוגע באותו אדם הנוגע עתה במת נעשה טמא טומאת שבעה לענין זה, \u0003אבל ל\u0004ענין \u0003נזיר\u0004 שייחשב בשל כך טמא ויביא קרבן כאדם שהיה נוגע במת, \u0003ו\u0004כן \u0003עושה פסח\u0004 שיימנע מלהקריב קרבן פסח בגלל שנגע — \u0003לא. ואי אמרת דאורייתא\u0004 \u0005[ואם אתה אומר\u0006 שהיא מן התורה\u0005]\u0006 \u0003מאי שנא\u0004 \u0005[מה ההבדל\u0006\u0005]\u0006 בין תרומה לנזיר?","ומשיבים: יש לחלק במושג \"טומאה בחיבורין\", כי \u0003כאן\u0004 כשמחלקים בין טומאת תרומה וטומאת נזיר, הרי זה \u0003בחיבורי אדם באדם,\u0004 שאדם אחד נוגע במת ואדם אחר נוגע בו באותה שעה, שאז השני נטמא באמת רק מדברי סופרים. \u0003כאן בחיבורי אדם במת,\u0004 אם נוגע במת עצמו — הריהו כמחובר לטומאה מדין תורה.","ולפיכך יש מקום לומר כדברי רבה: \u0003אבל טומאה וטומאה,\u0004 שהיה טמא במגע טומאת מת, וחזר ונגע במת אחר \u0003לא\u0004 יתחייב על נגיעה במת אחר, אם הוא נוגע אותה שעה במת, \u0003דהא\u0004 \u0005[שהרי\u0006\u0005]\u0006 הוא \u0003מיטמא וקאים\u0004 \u0005[ועומד\u0006\u0005].\u0006","ומקשים: אם כן \u0003טומאה וביאה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 נאמר כך, שאם באותו אופן מדובר, נמצא שכשהוא נוגע במת נכנס לבית שהמת בתוכו, והרי גם כאן \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 הוא \u0003מיטמא וקאי\u0004 \u0005[ועומד\u0006\u0005]\u0006 ומדוע ילקה על הטומאה שוב! \u0003אמר ר' יוחנן:\u0004 אף בטומאה וביאה יש להבחין בין שני אופנים; \u0003כאן בבית\u0004 שאם היה טהור ונכנס לבית שהמת בתוכו — לוקה משום ביאה ומשום טומאה שבאו עליו כאחת,","\u0003כאן בשדה\u0004 שאם הוא נוגע במת, ובעודו נוגע במת נכנס לבית — אינו מתחייב גם על הביאה."],["\u0003בבית נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 אינו מובן מדוע יהא חייב שתים, שהרי \u0003כיון דאעיל ידיה\u0004 \u0005[שהכניס\u0006 את ידו\u0005] —\u0006 \u0003איסתאב\u0004 \u0005[נטמא\u0006\u0005],\u0006 שדרך אדם בכניסתו לבית שידו נכנסת קודם לגופו, ואוהל המת נחשב כמלא טומאה ונטמא בכך, ואם כן \u0003כי עייל כולי\u0004 \u0005[כאשר נכנס כולו\u0006\u0005],\u0006 \u0003האי\u0004 \u0005[זה\u0006\u0005]\u0006 \u0003טמא הוא\u0004 כבר!","\u0003אלא אמר ר' אלעזר,\u0004 אם \u0003צירף\u0004 (הכניס) \u0003ידו\u0004 קודם בפנים הבית \u0003משום טומאה —\u0004 \u0003איכא\u0004 \u0005[יש\u0006\u0005],\u0006 \u0003משום ביאה —\u0004 \u0003ליכא\u0004 \u0005[אין\u0006\u0005],\u0006 \u0003ו\u0004אולם אם \u0003צירף גופו\u0004 וידיו, ונכנס כולו בבת אחת — \u0003טומאה וביאה בהדי הדדי קאתו\u0004 \u0005[זו עם זו,\u0006 ביחד, הן באות\u0005]\u0006 ובאופן זה מדובר שמתחייב שתיים. ומקשים: \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003אי אפשר\u0004 ש\u0003לא עייל\u0004 \u0005[נכנס\u0006\u0005]\u0006 \u0003חוטמו ברישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 \u0003ונחית ליה\u0004 \u0005[וירדה עליו\u0006\u0005]\u0006 \u0003טומאה\u0004 מיד עם כניסתו, וקודם שנכנס כל גופו כבר טמא הוא!","\u0003אלא אמר רבא: הכניס ידו, משום טומאה —\u0004 \u0003איכא\u0004 \u0005[יש\u0006\u0005],\u0006 \u0003משום ביאה —\u0004 \u0003ליכא\u0004 \u0005[אין\u0006\u0005],\u0006 שאין לומר שנחשב הדבר שהוא בבית. אבל \u0003הכניס גופו\u0004 והשתדל שלא יכנס ראשו תחלה אלא היה זקוף ונכנס בבת אחת — \u0003טומאה וביאה בהדי הדדי קא אתיין\u0004 \u0005[זו עם זו,\u0006 ביחד, הן באות\u0005].\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003אי אפשר\u0004 ש\u0003לא עייל אצבעתא דכרעיה ברישא ונחת להו\u0004 \u0005[הכניס את אצבעות רגליו בתחילה וירדה עליהן\u0006\u0005]\u0006 \u0003טומאה\u0004 וממילא נטמא כולו עוד לפני שנכנס כל גופו!","\u0003אלא אמר רב פפא: כגון שנכנס\u0004 (שהכניסוהו) לבית \u0003בשידה\u0004 (ארון) \u0003תיבה\u0004 א\u0003ו מגדל\u0004 (מבנה גדול של עץ), שאם היו גדולים מארבעים סאה אינם מקבלים טומאה וחוצצים בפני הטומאה, \u0003ובא חבירו ופרע\u0004 (ופתח) \u0003עליו את המעזיבה\u0004 (הגג) של המבנים הללו, שבמקרה זה \u0003טומאה וביאה בהדי הדדי קאתיין\u0004 \u0005[ביחד\u0006 הן באות\u0005].\u0006 \u0003מר בר רב אשי אמר: כגון דעייל\u0004 \u0005[שנכנס\u0006\u0005]\u0006 לבית \u0003כשהוא,\u0004 המת שהיה שם, \u0003גוסס, ונפק נשמתיה אדיתיב\u0004 \u0005[ויצאה נשמתו כש\u0006הוא, זה שנכנס, יושב שם\u0005]\u0006 ש\u0003טומאה וביאה בהדי הדדי קאתיין\u0004 \u0005[זו עם זו,\u0006 ביחד, הן באות\u0005].\u0006","ובענין זה של איסור טומאה במי שהיה גוסס ומת \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 נאמר באיסור טומאה לכהנים \u0003\"\u0004לא ייטמא בעל בעמיו \u0003להחלו\"\u0004 (ויקרא כא, ד), ודרשו מכאן כי אין איסור זה חל \u0003עד שעה שימות,\u0004 שלפני כן אינו נטמא ומחלל את כהונתו. \u0003רבי אומר:\u0004 נאמר בנזיר \"לא יטמא להם במותם\" (במדבר ו, ז), ויש לדייק כי רק \u0003\"במותם יטמא\",\u0004 ואינו נטמא \u0003עד שימות\u0004 המת.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל ביניהם\u0005],\u0006 שהם דורשים לכאורה אותו דבר מפסוקים אחרים? \u0003אמר ר' יוחנן: משמעות דורשין איכא בינייהו\u0004 \u0005[יש ביניהם\u0006\u0005].\u0006 כלומר, שניהם מסכימים להלכה, אלא שכל אחד דורש מפסוק אחר, ומשתמש בפסוק השני לענין אחר. \u0003ריש לקיש אמר:\u0004 לענין \u0003גוסס איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005];\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת מי שאומר\u0005]\u0006 שלומד את הדין \u0003מ\"להחלו\" —\u0004 \u0003אפילו גוסס\u0004 בכלל איסור טומאה, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת מי שאומר\u0005]\u0006 שלומד את הדין מ\u0003\"במותם\" —\u0004 \u0003עד שימות —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 אבל \u0003גוסס —\u0004 \u0003לא,\u0004 אינו מטמא.","ושואלים לשיטת ריש לקיש: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת מי שאומר\u0005]\u0006 \u0003מ\"להחלו\", הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"במותם\"!\u0004 ומה דורש הוא בדיוק הכתוב הזה? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו\u0006\u0005]\u0006 הכתוב \u0003ל\u0004כמו שדרש \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 הכתוב מדגיש \"במותם\" לומר: \u0003במותם אינו מטמא, אבל מטמא\u0004 הוא \u0003בנגעתם\u0004 (בנגע הצרעת שלהם) \u0003ובזיבתם,\u0004 שלא הוזהר הנזיר אלא על טומאת המת בלבד.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת מי שאומר\u0005]\u0006 ולומד מן הכתוב \u0003\"במותם\"\u0004 לענין זמן האיסור, \u0003הא מיבעי ליה להאי סברא\u0004 \u0005[הרי צריך\u0006 הוא את זה הכתוב לסברה זו\u0005]!\u0006 ומשיבים: \u0003אם כן לימא קרא\u0004 \u0005[\u0006שיאמר הכתוב\u0005]\u0006 \u0003\"במות\", מאי\u0004 \u0005[מהי\u0006\u0005]\u0006 ההדגשה \u0003\"במותם\" —\u0004 \u0003שמעת מינה תרתי\u0004 \u0005[לומד אתה מכאן שני\u0006 דברים\u0005],\u0006 הן להוציא גוסס, והן להוציא כל טומאה מחוץ לטומאת המת.","ושואלים מצד אחר: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת מי שאומר\u0005]\u0006 שהמקור הוא ממה שנאמר \u0003\"במותם\", הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"להחלו\"\u0004 ומה עושה הוא בכתוב זה? ומשיבים: \u0003\"להחלו\" להכי הוא דאתא\u0004 \u0005[ל\u0006דבר זה הוא שבא\u0005],\u0006 ללמד שהאיסור להיטמא הוא דווקא \u0003במי שאינו מחולל, יצא זה\u0004 שכבר נטמא \u0003שמחולל\u0004 הוא \u0003ועומד,\u0004 שאין עליו דין איסור טומאת המת.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת מי שאומר\u0005]\u0006 ולומד את הדבר \u0003מ\"להחלו\", הא מיבעי ליה להאי סברא\u0004 \u0005[הרי צריך אותו\u0006 כתוב לסברה זו\u0005]!\u0006 ומשיבים: \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 \u0003\"להחל\", מאי \"להחלו\" —\u0004 \u0003שמעת מינה תרתי\u0004 \u0005[לומד אתה מכאן שני\u0006 דברים\u0005],\u0006 הן שאסור להיטמא לגוסס, והן שאין איסור למי שכבר טמא לחזור ולהיטמא.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 ממה ששנינו: \u0003אדם אינו מטמא אלא עד שתצא נפשו. ואפילו\u0004 הוא \u0003מגוייד\u0004 (חתוך חתכים קשים) \u0003ואפילו\u0004 הוא \u0003גוסס. ולמאן דאמר\u0004 \u0005[ול\u0006דעת מי שאומר\u0005]\u0006 \u0003מ\"להחלו\" הא קתני\u0004 \u0005[הרי שנינו\u0006\u0005]\u0006 ש\u0003אינו מטמא!\u0004 ומשיבים: \u0003לענין טמויי\u0004 \u0005[לטמא\u0006\u0005],\u0006 באמת אינו מיטמא \u0003עד דנפקא נפשיה\u0004 \u0005[שיוצאת נפשו\u0006 של המת\u0005],\u0006 \u0003לענין אתחולי\u0004 \u0005[חילול\u0006\u0005]\u0006 קדושת כהונתו, \u0003הא איתחיל\u0004 \u0005[הרי\u0006 כבר התחלל\u0005]\u0006 בזמן שטיפל בגוסס."],["\u0003אמר רב חסדא אמר רב:\u0004 אם \u0003נקטע ראשו של אביו\u0004 (או קרוב אחר שכהן מותר להיטמא לו) של הכהן — \u0003אינו מטמא לו. מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר — \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"\u0004לנפש לא יטמא בעמיו כי אם... ו\u0003לאביו\"\u0004 (ויקרא כא, א-ב), לומר: \u0003בזמן שהוא שלם, ולא בזמן שהוא חסר. אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב המנונא\u0004 לרב חסדא: \u0003אלא מעתה,\u0004 לדבריך, \u0003קאזיל בפקתא\u0004 \u0005[\u0006אם היה הולך בבקעה\u0005]\u0006 של \u0003ערבות\u0004 מקום שהיו מצויים בו שודדים, \u0003ופסקוה גנבי לרישיה, הכי נמי דלא ליטמא ליה\u0004 \u0005[וחתכו גנבים את ראשו, כך גם כן\u0006 תאמר שאינו מיטמא לו\u0005]\u0006 הכהן, כיון שהוא קטוע ראש ואינו שלם?","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003מת מצוה קאמרת\u0004 \u0005[אומר אתה\u0006\u0005]?\u0006 בזה בוודאי אין לומר כן, כי \u0003השתא\u0004 \u0005[עכשיו\u0006\u0005]\u0006 הרי \u0003יש לומר באחריני מיחייב\u0004 \u0005[\u0006שבאחרים הוא חייב\u0005]\u0006 להיטמא להם גם אם אינם קרוביו, לפי שכהן ונזיר מיטמאים למתי מצוה, על מנת לטפל בקבורתם, \u0003באביו\u0004 שהוא מת מצוה \u0003לא כל שכן\u0004 שמותר ואף מצוה ליטמא לו, אף באופן כזה שנקטע ראשו?","ושואלים: \u0003והאי\u0004 \u0005[וזה\u0006\u0005]\u0006 \u0003מת מצוה הוא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו מת מצוה\u0004 שמותר לכהן להיטמא לו — \u0003כל שאין לו קוברין\u0004 מלבד כהן זה. ואם המת מצוי במקום שהיה \u0003קורא ואחרים עונין אותו —\u0004 \u0003אין זה\u0004 נחשב כ\u0003מת מצוה. והא אית ליה ברא\u0004 \u0005[והרי יש לו בן\u0006\u0005],\u0006 ואם כן שוב אין אביו מוגדר כמת מצוה, וצריך בנו הכהן לדאוג לכך שאנשים אחרים יטפלו בקבורתו! ומשיבים: \u0003כיון דקאזיל באורחא\u0004 \u0005[ש\u0006הוא הולך בדרך\u0005] —\u0006 \u0003כמי שאין לו קוברים דמי\u0004 \u0005[\u0006הוא נחשב\u0005].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על רב חסדא ממה ששנינו בפסוק \u0003\"\u0004ולאחותו הבתולה הקרובה אליו אשר לא היתה לאיש \u0003לה יטמא\"\u0004 (ויקרא כא, ג), וייתור הלשון \"לה\" בא ללמדנו: \u0003לה\u0004 בשלמותה \u0003הוא מטמא, ואינו מטמא לאיבריה\u0004 אם נחתך ממנה איבר בחייה, \u0003לפי שאינו מטמא לאבר מן החי של אביו.\u0004 \u0003אבל מחזיר\u0004 (מחזר, מחפש) \u0003הוא על עצם כשעורה,\u0004 שאם נטמא כבר לגופו מותר לחפש ולהשלים אפילו עצם שנחתכה ממנו כדי לקוברה, אף שיש בה כדי שיעור טומאה.","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 פירוש \u0003\"מחזיר הוא על עצם כשעורה\"? לאו למימרא\u0004 \u0005[האם לא לומר\u0006\u0005]\u0006 \u0003דאי מיחסר פורתא\u0004 \u0005[שאם חסר\u0006 אביו המת מעט\u0005]\u0006 כגון עצם אחת, מיטמא לו? והרי זה שלא כדברי רב חסדא בשם רב שרק אם אביו שלם מיטמא לו!","ומשיבים: \u0003לא,\u0004 מכאן אין להקשות, כי \u0003ההיא\u0004 \u0005[אותה\u0006\u0005]\u0006 ברייתא, שיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 \"לה יטמא\" (ויקרא כא, ג) — \u0003לה מיטמא ואינו מיטמא לאבריה, שאינו מיטמא על אבר מן החי של אביו, אבל מיטמא הוא\u0004 אפילו \u0003לאבר מן המת של אביו.\u0004 אבל רב חסדא אמר כחכמים החולקים על ר' יהודה, והם סבורים שאינו מיטמא אלא לגוף שלם.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 של \u0003רב כהנא ב\u0004שם \u0003ר' אליעזר בן יעקב:\u0004 \"לה יטמא\" (ויקרא כא, ג) — \u0003לה\u0004 הוא \u0003מיטמא,\u0004 כשהיא כולה, \u0003ואינו מיטמא לאברים\u0004 ממנה, ובא הכתוב ללמד: \u0003פרט לכזית מן המת, וכזית נצל\u0004 (ליחה היוצאת מן המת) \u0003ומלא תרווד רקב\u0004 של המת.","\u0003יכול לא יטמא לשדרה ולגולגולת\u0004 או \u0003לרוב בניינה ולרוב מניינה\u0004 של גוויית אחותו — לכך \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 בפתיחת פרשה זו של טומאת הכהנים: \u0003\"\u0004אמור אל הכהנים... \u0003ואמרת אליהם\"\u0004 (ויקרא כא, א) וכפילות זו של אמירה באה לומר כי \u0003הוסיף לך הכתוב טומאה אחרת,\u0004 שלאלו מותר הכהן להיטמא."],["\u0003יכול לא יטמא לשדרה ולגולגולת ולרוב בניינו ולרוב מניינו של אחרים. אמרת: מה אחותו מיוחדת שגופה תלוי בו\u0004 באחיה שהוא המטפל בקבורתה, \u0003ומיטמא לשדרה ולגולגולת ולרוב בניינה ולרוב מניינה —\u0004 \u0003אף כל שגופו תלוי בו,\u0004 דהיינו שאר קרובים, \u0003מיטמא לשדרה ולגולגולת ולרוב בניינו ולרוב מניינו.\u0004 וקשה לשיטת רב חסדא בשם רב לפיה אסור ליטמא לאביו (או קרוב אחר) שנקטע ראשו!","ומשיבים: הברייתא \u0003ההיא נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 שיטת \u0003ר' יהודה היא. ורב\u0004 ש\u0003אמר —\u0004 \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת תנא זה\u0005]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003מעשה שמת אביו של ר' יצחק\u0004 הכהן \u0003ב\u0004מקום הנקרא \u0003גינזק, ובאו והודיעוהו לאחר שלש שנים, ובא ושאל את ר' יהושע בן אלישע וארבעה זקנים\u0004 \u0005[שעמו\u0006\u0005]\u0006 האם רשאי ליטמא לאביו להביאו לקברי אבותיו,","\u0003ואמרו:\u0004 שנינו \u0003\"לאביו\"\u0004 (ויקרא כא, ב) — \u0003בזמן שהוא שלם, ולא בזמן שהוא חסר.\u0004 ובתוך שלוש שנים בוודאי חסר משהו ממנו, ולכן אין הכהן רשאי עוד להיטמא לו.","\u0003שלשה מינין\u0004 של איסורים \u0003אסורין בנזיר: הטומאה\u0004 למת, \u0003והתגלחת, ו\u0004אכילה או שתיה של כל דבר \u0003היוצא מן הגפן. חומר\u0004 (חומרה) יש \u0003ב\u0004איסורי \u0003טומאה ובתגלחת מביוצא מן הגפן: שהטומאה והתגלחת\u0004 אם עשה אותן — \u0003סותרין\u0004 את נזירותו, וצריך למנות שוב ימי נזירות, \u0003ו\u0004אילו \u0003היוצא מן הגפן\u0004 אף שאכל או שתה באיסור — \u0003אינו סותר\u0004 את נזירותו.","ומצד שני \u0003חומר ביוצא מן הגפן מבטומאה ובתגלחת, שהיוצא מן הגפן לא הותר מכללו,\u0004 שאין בו יוצא מהכלל, \u0003ו\u0004אילו \u0003טומאה ותגלחת הותרו מכללן,\u0004 כיצד — \u0003בתגלחת מצוה\u0004 כגון זו של מצורע שנטהר תוך ימי נזירותו, \u0003ובמת מצוה\u0004 שמותר לו לנזיר לטפל בו אף שנטמא בכך.","\u0003וחומר בטומאה מבתגלחת, שהטומאה,\u0004 אם נטמא הנזיר — \u0003סותרת את הכל,\u0004 את כל ימי נזירותו, ומתחיל למנות הכל מתחילה, \u0003וחייבין עליה קרבן\u0004 ואחר כך מתחיל את ימי הנזירות מחדש, \u0003ו\u0004אילו \u0003תגלחת אינה סותרת אלא שלשים\u0004 יום לכל היותר, \u0003ואין חייבין עליה קרבן.\u0004","על ההלכות שבמשנה שואלים: \u0003ו\u0004נאמר כי \u0003טומאה\u0004 בנזיר \u0003לא תותר מכללה\u0004 במת מצוה, ונלמד \u0003קל וחומר מ\u0004איסור \u0003יין: ומה יין\u0004 שאיסורו קל \u0003ש\u0004הרי \u0003אינו סותר\u0004 את הנזירות ובכל זאת \u0003לא הותר מכללו, טומאה\u0004 שהיא חמורה \u0003ש\u0004הרי היא \u0003סותרת —\u0004 \u0003אינו דין שלא תותר מכללה?\u0004","\u0003תלמוד לומר\u0004 שבנוסף לאיסור הכללי \"על נפש מת לא יבוא\" (במדבר ו, ו) נאמר גם \u0003\"לאביו ולאמו\u0004 לאחיו ולאחותו \u0003לא יטמא\u0004 להם במותם\u0003\"\u0004 (במדבר ו, ז) ומפירוט זה נלמד: \u0003לאביו ולאמו\u0004 דווקא \u0003לא יטמא —\u0004 \u0003אבל מיטמא הוא למת מצוה.\u0004","ומציעים: אם כן יש לשאול להיפך: \u0003ויין יותר מכללו\u0004 ב\u0003קל וחומר מטומאה; מה טומאה שהיא סותרת —\u0004 \u0003הותרה מכללה, יין שאינו סותר —\u0004 \u0003אינו דין שיותר מכללו\u0004 לצורך מצוה, כגון שנשבע לשתות יין? ומשיבים: לכך \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 בנזיר: \u0003\"מיין ושכר יזיר\"\u0004 (במדבר ו, ג) וכפילות המלים \"יין ושכר\" באה \u0003לאסור יין מצוה כיין רשות.\u0004","ושואלים עוד: \u0003ו\u0004נאמר ש\u0003יין יסתור את הכל,\u0004 שאם שתה יין ייבטלו כל ימי הנזירות שכבר מנה, ב\u0003קל וחומר מטומאה; מה טומאה שהותרה מכללה —\u0004 \u0003סותרת את הכל, יין שלא הותר מכללו —\u0004 \u0003לא כל שכן שיסתור?\u0004","ומשיבים: לכך \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"והימים הראשנים יפלו כי טמא נזרו\"\u0004 (במדבר ו, יב), וההדגשה \"כי טמא נזרו\" מיותרת שהרי בנזיר שנטמא מדובר, אלא ללמדנו: דווקא \u0003טומאה סותרת ואין היין סותר.\u0004","ושואלים: \u0003והתגלחת תסתור את הכל,\u0004 ב\u0003קל וחומר מטומאה; ומה טומאה שלא עשו בה מטמא כמטמא,\u0004 שהמטמא את הנזיר אינו עובר על איסור הנזירות, אלא רק הנזיר המיטמא, ובכל זאת \u0003סותרת את הכל, תגלחת שעשו בה מגלח כמתגלח,\u0004 שגם המגלח את הנזיר עובר על איסור הנזירות — \u0003אינו דין שתסתור את הכל?\u0004","ומשיבים: לכך \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"והימים הראשונים יפלו כי טמא נזרו\"\u0004 (במדבר ו, יב) וההדגשה \"כי טמא נזרו\" באה ללמד: \u0003טומאה סותרת את הכל\u0004 (\"הימים הראשונים\"), \u0003ואין תגלחת סותרת את הכל.\u0004","ומציעים: אם כן נשאל להיפך: \u0003וטומאה נעשה בה מטמא כמיטמא, קל וחומר מתגלחת; ומה תגלחת שאינה סותרת אלא שלשים —\u0004 \u0003עשה בה מגלח כמתגלח, טומאה שהיא סותרת את הכל —\u0004 \u0003אינו דין שנעשה בה מטמא כמיטמא?\u0004","ומשיבים, לכך \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"\u0004וכי ימות מת עליו בפתע פתאום \u0003וטמא ראש נזרו\"\u0004 (במדבר ו, ט) דווקא \u0003למטמא ראש נזרו\u0004 שלו, הוא שנאמר האיסור קודם לכן, אבל לא לאחרים שטימאו אותו.","ומציעים, אם כן נשאל להיפך: \u0003ותגלחת לא נעשה בה מגלח כמתגלח, קל וחומר מטומאה; ומה טומאה\u0004 שהיא חמורה, \u0003ש\u0004הרי \u0003היא\u0004 \u0003סותרת את הכל —\u0004 \u0003לא עשו בה מטמא כמיטמא. תגלחת שאינה סותרת אלא שלשים יום —\u0004 \u0003לא כל שכן שלא נעשה\u0004 בה \u0003מגלח כמתגלח?\u0004","ומשיבים, לכך \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"תער לא יעבר על ראשו\"\u0004 (במדבר ו, ה), \u0003קרי ביה\u0004 \u0005[קרא בו\u0006\u0005]\u0006 במקרא זה שנאמר בלשון כללית: \u0003לא יעבור הוא\u0004 הנזיר, \u0003ולא יעבור —\u0004 \u0003לאחר.\u0004","ושואלים: \u0003ותגלחת לא תותר מכללה\u0004 במצורע, \u0003קל וחומר מיין; ומה יין שאינו סותר —\u0004 \u0003לא הותר מכללו, תגלחת שסותרת\u0004 את הנזירות — \u0003אינו דין שלא תותר מכללה?\u0004 ומשיבים, לכך \u0003אמר רחמנא\u0004 \u0005[אמרה תורה\u0006\u0005]\u0006 במצורע: \"וגלח את כל שערו\", והוסיפה \u0003\"\u0004את \u0003ראשו\"\u0004 (ויקרא יד, ט) \u0003ואמר רחמנא\u0004 \u0005[ואמרה תורה\u0006\u0005]\u0006 והוסיפה: \u0003\"\u0004ואת \u0003זקנו\"\u0004 (ויקרא יד, ט), ללמד שלמרות איסור נזיר — בכל זאת מגלח.","ומציעים: אם כן נשאל להיפך: \u0003ותגלחת לא תסתור כלל, קל וחומר מיין ומה יין שלא הותר מכללו —\u0004 \u0003אינו סותר, תגלחת שהותרה מכללה —\u0004 \u0003אינו דין שלא תסתור?\u0004 ומשיבים: \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 לקיים בו \u0003גידול שער, והא ליכא\u0004 \u0005[והרי אין\u0006\u0005]\u0006 לו כעת, ולכן צריך להמתין עד שיגדל שערו.","שואלים: \u0003ויין יסתור שלשים יום, קל וחומר מתגלחת; ומה תגלחת שהותרה מכללה —\u0004 \u0003סותרת, יין שלא הותר מכללו —\u0004 \u0003אינו דין שיסתור?\u0004 ומשיבים: \u0003מידי\u0004 \u0005[כלום\u0006\u0005]\u0006 \u0003הוא טעמא\u0004 \u0005[הטעם\u0006\u0005]\u0006 שסותר בתגלחת שלושים \u0003אלא משום גידול שער,\u0004 שצריך שבסוף נזירותו יהא שערו מגודל בשיעור זה על מנת לגלחו, ל\u0003גבי יין —\u0004 \u0003הא קאים\u0004 \u0005[הרי עומד,\u0006 נשאר\u0005]\u0006 \u0003שערו,\u0004 וכיון שלא נעשה בנזיר עצמו שינוי, אין שתיית היין סותרת."],["\u0003תגלחת טומאה\u0004 של הנזיר שנטמא למת תוך כדי נזירותו \u0003כיצד\u0004 היא נעשית? \u0003היה מזה,\u0004 כלומר, מזים על הנזיר מי פרה אדומה \u0003ב\u0004יום ה\u0003שלישי וב\u0004יום ה\u0003שביעי\u0004 לאחר שנטמא, ככל טמא מת, \u0003ומגלח\u0004 את שערו \u0003ב\u0004יום ה\u0003שביעי, ומביא קרבנותיו ב\u0004יום ה\u0003שמיני. ואם גילח בשמיני —\u0004 \u0003מביא קרבנותיו בו ביום,\u0004 אלו \u0003דברי ר' עקיבא. אמר לו ר' טרפון: מה בין זה למצורע\u0004 שאף הוא מגלח ביום השביעי ומביא קרבנותיו ביום השמיני, אך אם גילח ביום השמינית מביא קרבנותיו ביום התשיעי, שאין מביא קרבן ביום תגלחתו?","\u0003אמר לו: זה,\u0004 נזיר שנטמא, \u0003טהרתו תלויה בימיו,\u0004 שביום השביעי הוא טובל, ככל טמא מת, ואם כן הריהו טהור כבר ביום השמיני \u0003ו\u0004אולם \u0003מצורע טהרתו תלויה בתגלחתו\u0004 ואין טבילה עולה לו לפני כן, וצריך לטבול שוב. \u0003ואינו מביא,\u0004 כלומר, אינו יכול להביא \u0003קרבן אלא אם כן היה מעורב שמש\u0004 (שהעריבה השמש לאחר שטבל ונטהר), ובלילה אין מקריבים קרבן, ולכן צריך לדחות את הבאת הקרבן למחר.","על האמור במשנתנו שואלים: האם ר' טרפון \u0003קיבלה\u0004 לסברה זו \u0003מיניה\u0004 \u0005[ממנו,\u0006 מר' עקיבא\u0005],\u0006 \u0003או לא? תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לכך ממה \u0003דתני\u0004 \u0005[ששנה\u0006\u0005]\u0006 \u0003הלל\u0004 (האמורא): \u0003גילח\u0004 הנזיר \u0003בשמיני —\u0004 \u0003מביא קרבנותיו בתשיעי. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר שר' טרפון \u0003קיבלה מיניה\u0004 \u0005[ממנו\u0006\u0005]\u0006 אם כן \u0003ליתי\u0004 \u0005[שיביא\u0006\u0005]\u0006 \u0003קרבנותיו בשמיני\u0004 עצמו כדעת ר' עקיבא! אלא ודאי ברייתא זו היא כדעת ר' טרפון, שלא קיבל את סברתו של ר' עקיבא.","\u0003אמר רבא: לא קשיא\u0004 \u0005[אין\u0006 זה קשה\u0005],\u0006 אפשר לומר שר' טרפון הודה לדברי ר' עקיבא במקרה שגילח הנזיר בשמיני, ואולם יש להבחין בין המקרים, \u0003הא\u0004 \u0005[זה\u0006\u0005]\u0006 במשנתנו — מדובר ש\u0003טבל בשביעי,\u0004 ובשמיני הריהו איפוא טהור גמור ויכול להביא קרבן בו ביום לאחר שיתגלח, \u0003הא\u0004 \u0005[זה\u0006\u0005],\u0006 בברייתא ששנה הלל — מדובר ש\u0003לא טבל בשביעי,\u0004 ואם הוא טובל בשמיני, הריהו יכול להביא קרבנותיו, ככל טבול יום, רק לאחר הערב שמש, ביום התשיעי.","\u0003אמר אביי: אשכחתינהו לחבריה\u0004 \u0005[מצאתי,\u0006 פגשתי את בני החבורה\u0005]\u0006 של \u0003רב נתן בר הושעיא דיתבין וקאמרין\u0004 \u0005[שיושבים ואומרים\u0006\u0005]:\u0006 נאמר בזב שטובל ביום השביעי לטהרתו \u0003\"\u0004וביום השמיני יקח לו שתי תורים או שני בני יונה \u0003ובא לפני ה' אל פתח אהל מועד ונתנם אל הכהן\"\u0004 (ויקרא טו, יד) \u0003אימתי הוא\u0004 \u0005[בא\u0006\u0005]\u0006 אל העזרה להקריב קרבנותיו? דווקא \u0003בזמן שהוא טבל\u0004 ביום השביעי, \u0003ועשה הערב שמש —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 אבל אם \u0003לא טבל ועשה הערב שמש —\u0004 \u0003לא.\u0004","\u0003אלמא קסבר\u0004 \u0005[מכאן שסבור\u0006\u0005]\u0006 אותו תנא כי \u0003טבול יום של זב —\u0004 \u0003כזב\u0004 עצמו \u0003דמי\u0004 \u0005[נחשב\u0006\u0005],\u0006 שכשם שהזב בטומאתו אסור להיכנס למחנה לוייה, כך זב ביום שטבל אינו רשאי להיכנס לעזרה, ולפיכך צריך להמתין עד שתערב השמש ויטהר לגמרי.","ומוסיף אביי, \u0003אמינא להון אנא\u0004 \u0005[אמרתי להם אני\u0006\u0005]:\u0006 \u0003אלא מעתה גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר טמא נמי\u0004 \u0005[גם כן\u0006\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 בו \u0003\"(והביא אותם)\u0004 וביום השמיני יביא שתי תורים או שני בני יונה \u0003אל הכהן אל פתח אהל מועד\"\u0004 (במדבר ו, י) נפרש כן באותו אופן: \u0003אימתי הוא\u0004 \u0005[בא\u0006\u0005]\u0006 אל העזרה להקריב את קרבנו — \u0003בזמן שטבל ועשה הערב שמש.\u0004"],["\u0003מכדי\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003שערי ניקנור\u0004 שכל מחוסרי כפרה עומדים שם בהביאם את קרבנותיהם \u0003היכא קיימין\u0004 \u0005[היכן\u0006 הם עומדים נמצאים\u0005] —\u0006 \u0003בשערי לוייה,\u0004 כלומר, במקום שהוא מצד הדין מחנה לויים, ולא במקדש עצמו (\"מחנה שכינה\").","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טמא מת מותר ליכנס במחנה לוייה, ולא טמא מת בלבד —\u0004 \u0003אלא אפילו מת עצמו\u0004 אפשר להכניס לשם, \u0003ש\u0004כן \u0003נאמר \"ויקח משה את עצמות יוסף עמו\"\u0004 (שמות יג, יט) \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עמו\" —\u0004 \u0003עמו במחיצתו,\u0004 כלומר, \u0003עמו במחנה לוייה.\u0004 משמע שאפשר להכניס אפילו מת עצמו למחנה הלויים, וכל שכן נזיר שנטמא במת וכבר נטהר בהזאה וטבל. ואם כן מה שהנזיר מביא את קרבנו ביום השמיני אינו מפני איסור כניסה למקדש. ומכאן נלמד גם לזב, שההלכה שאינו מקריב קרבנותיו אלא ביום השמיני אינה תלויה בהיותו טבול יום קודם לכן, ואין להוכיח מכך שטבול יום של זב דינו כזב.","\u0003אלא אמר אביי:\u0004 יש להבין את הברייתא בדרך שונה במקצת, ושלא כהבנת החבורה של רב נתן בר הושעיא. וכך צריך לומר: \u0003טבול יום של זב\u0004 ודווקא זב שראה שלוש ראיות (ולא זה שראה שתים בלבד) — \u0003כזב דמי\u0004 \u0005[נחשב\u0006\u0005]\u0006 לענין איסור כניסה. אולם איסור כניסתו למקדש אינו משום שהוא טבול יום, כי גם אם היה מותר מטעם זה כפי שהוא בזב שראה שתי ראיות, \u0003ואפילו הכי\u0004 \u0005[כך\u0006\u0005],\u0006 \u0003כיון\u0004 שהוא \u0003מחוסר כפרה,\u0004 שלא קרב קרבנו — הריהו טמא לענין זה, ומשום כך הוא \u0003לא עייל\u0004 \u0005[נכנס\u0006\u0005].\u0006","והוא מסביר: וטעמו של דבר, שהרי נאמר בזב \"ובא לפני ה' אל פתח אוהל מועד\" (ויקרא טו, יד), \u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003במחנה לוייה\u0004 (בשער ניקנור) \u0003קאי\u0004 \u0005[\u0006הוא עומד\u0005]\u0006 כשבא להקריב את קרבנו, \u0003אמאי קא קרי ליה\u0004 \u0005[מדוע קורא לו\u0006\u0005]\u0006 למקום זה \u0003\"אהל מועד\"?\u0004 אלא \u0003למימרא\u0004 \u0005[לומר\u0006\u0005]:\u0006 \u0003מה התם\u0004 \u0005[שם\u0006\u0005]\u0006 באהל מועד עצמו, שהוא \"מחנה שכינה\" \u0003מחוסר כפרה לא עייל\u0004 \u0005[נכנס\u0006\u0005].\u0006 — \u0003אף למחנה לוייה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003מחוסר כפרה לא עייל\u0004 \u0005[נכנס\u0006\u0005].\u0006","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם,\u0006 במחנה שכינה, מנין לנו\u0005]\u0006 שמחוסר כפרה אינו נכנס? ומשיבים, \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בקשר לאיסור טומאה במשכן: \"טמא יהיה עוד טומאתו בו\" (במדבר יט, יג), וכך דרשו: \u0003\"טמא יהיה\" —\u0004 \u0003לרבות טבול יום\u0004 לאיסור כניסה לקודש, \u0003\"עוד טמאתו בו\" —\u0004 \u0003לרבות מחוסר כפרה,\u0004 שכל עוד לא מביא קרבן טהרתו הריהו אסור להיכנס.","\u0003תגלחת הטהרה\u0004 של נזיר, שהשלים ימי נזירותו כדין, \u0003כיצד\u0004 היא נעשית? — \u0003היה מביא\u0004 \u0003שלש בהמות,\u0004 אחת לקרבן \u0003חטאת,\u0004 ואחת ל\u0003עולה, ו\u0004אחת ל\u0003שלמים. ושוחט את השלמים ומגלח\u0004 את שערו \u0003עליהם\u0004 (לאחר ששחטם), אלו \u0003דברי ר' יהודה. ר' אלעזר אומר: לא היה מגלח אלא על החטאת, שהחטאת קודמת\u0004 לשאר קרבנות \u0003בכל מקום\u0004 ואותה מביא ראשונה ומגלח שערו לאחר שחיטתה. \u0003ואם גלח על אחת משלשתן,\u0004 כלומר, על אחרת — בדיעבד \u0003יצא.\u0004","\u0003רבן שמעון בן גמליאל אומר: הביא\u0004 הנזיר \u0003שלש בהמות, ולא פירש\u0004 איזו מהן מיועדת לאיזה קרבן, \u0003הראויה לחטאת\u0004 שהיא כבשה נקבה בת שנתה — \u0003תקרב חטאת,\u0004 הראויה \u0003לעולה\u0004 (כבש זכר בן שנתו) \u0003תקרב עולה,\u0004 הראויה \u0003לשלמים\u0004 (איל זכר בן שנתו השניה) \u0003תקרב שלמים.\u0004","תחילה מסבירים את שיטת ר' יהודה במשנתנו, שלא ניתן טעם לדבריו במשנה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 מה שנאמר \u0003\"וגלח הנזיר פתח אהל מועד\"\u0004 (במדבר ו, יח) — \u0003בשלמים הכתוב מדבר.\u0004 שהביטוי \"פתח אהל מועד\" הוא רמז לקרבן השלמים, \u0003שנאמר\u0004 בו ביטוי זה, ככתוב \u0003\"\u0004ואם זבח שלמים קרבנו... \u0003ושחטו פתח אהל מועד\"\u0004 (ויקרא ג, א-ב).","\u0003אתה אומר בשלמים הכתוב מדבר,\u0004 שכוונתו שמגלח לאחר הקרבת השלמים, \u0003או אינו אלא\u0004 שמגלח \u0003פתח אהל מועד ממש,\u0004 בפתח ההיכל, כמשמעות המילים? \u0003אמרת: אם כן\u0004 שעושה זאת בפתח — \u0003דרך בזיון הוא\u0004 שמגלח בפתח ההיכל, ואינו ראוי לעשות כן.","\u0003ר' יאשיה אומר: אינו צריך\u0004 לראיה זו, כי \u0003הרי אמרה תורה\u0004 \"ו \u0003לא תעלה במעלת על מזבחי\u0004 אשר לא תגלה ערוותך עליו\" (שמות כ, כג), ואם לדבר זה שהוא דרך בני אדם חששה תורה לבזיון, \u0003קל וחומר לדרך בזיון\u0004 ממש של גילוח.","\u0003[נוסח אחר במדרש בפרשה נשא (דף רמ\"ב): \"וגלח הנזיר פתח אוהל מועד\", ר' יאשיה אומר: בשלמים הכתוב מדבר, או אינו\u0004 אלא שמגלח בפתח אוהל מועד ממש? \u0003אם כך אמרה תורה \"לא תעלה\" וכו'\u0004 (שמות כ, כג) — \u0003קל וחומר לדבר שלא יגלח פתח אהל מועד, אלא בשלמים הכתוב מדבר\u0004\u0005].\u0006","\u0003ר' יצחק אומר: אינו צריך\u0004 לראיה עקיפה לומר שאין הנזיר מגלח בפתח ההיכל, שכן \u0003הרי הוא אומר\u0004 בנזיר: \u0003\"ולקח את שער ראש נזרו ונתן על האש\u0004 אשר תחת זבח השלמים\u0003\"\u0004 (במדבר ו, יח), ומכאן למדנו כי מדובר ב\u0003מי שאינו מחוסר אלא לקיחה ונתינה\u0004 של השיער שגולח, תחת דוד זבח השלמים שנמצא מחוץ לעזרה, ואין פעולה אחרת נוספת. \u0003יצא זה\u0004 שאם גילח בפתח ההיכל, נמצא \u0003שהוא מחוסר לקיחה, הבאה\u0004 מתחום אחד של קודש אל מקום אחר, \u0003ונתינה.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006\u0005]\u0006 בלשון אחרת, \u0003ר' יצחק אומר: בשלמים הכתוב מדבר. אתה אומר בשלמים הכתוב מדבר, או אינו אלא פתח אהל מועד ממש? תלמוד לומר: \"ולקח את שער ראש נזרו\u0004 ונתן על האש אשר תחת זבח השלמים \u0003\"\u0004לומר: באותו \u0003מקום שהיה מבשל\u0004 את השלמים, מחוץ לעזרה — \u0003שם היה מגלח.\u0004","\u0003אבא חנן אומר משום\u0004 \u0005[בשם\u0006\u0005]\u0006 \u0003ר' אליעזר:\u0004 מה שנאמר \u0003\"וגלח הנזיר פתח אהל מועד\"\u0004 בא ללמד לא לענין מקום הגילוח, אלא לגבי זמנו: \u0003כל זמן שאין פתח אהל מועד פתוח —\u0004 \u0003אינו מגלח,\u0004 שאינו רשאי לגלח אלא בשעות שבהן פתוח פתח ההיכל.","\u0003ר' שמעון שזורי אומר:\u0004 מה שנאמר \u0003\"וגלח הנזיר פתח אהל מועד\"\u0004 אינו בא ללמד לענין המקום, אלא להדגשה אחרת, לומר: נזיר \u0003ולא נזירה,\u0004 שאינה מגלחת ראשה במקדש,"],["\u0003שמא יתגרו בה\u0004 יצריהם של \u0003פרחי\u0004 (צעירי) \u0003כהונה\u0004 הנמצאים שם, משום שהיא מגלה את שיער ראשה בפניהם. \u0003אמר לו: לדבריך סוטה תוכיח, דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 \u0003בה \"והעמדה לפני ה'\"\u0004 (במדבר ה, טז) \u0003ולא חיישינן\u0004 \u0005[ואין אנו חוששים\u0006\u0005]\u0006 \u0003שמא יתגרו בה פרחי כהונה!\u0004","\u0003אמר להן:\u0004 יש הבדל בין נזירה לסוטה, שכן \u0003זו\u0004 הנזירה אם רוצה \u0003כוחלת\u0004 (צובעת את סביבות עיניה) \u0003ופוקסת\u0004 צובעת באודם את פניה, ולכן יש לחשוש לגירוי יצריהם של צעירי הכהנים. ואילו \u0003זו\u0004 הסוטה \u0003אינה כוחלת ו\u0004אינה \u0003פוקסת,\u0004 שמכערים אותה כדי שתיראה עלובה ומנוולת, ולכן אין לחשוש לגירוי.","לאחר שגילח הנזיר את שערו, \u0003היה נוטל שער ראש נזרו ומשלח\u0004 (משליך) את השיער להישרף \u0003תחת הדוד\u0004 בו נתבשלו השלמים. \u0003ואם גילח\u0004 הנזיר \u0003במדינה,\u0004 מחוץ למקדש — \u0003לא היה משלח תחת הדוד\u0004 שבמקדש. \u0003במה דברים אמורים —\u0004 \u0003בתגלחת הטהרה. אבל בתגלחת הטומאה לא היה משלח\u0004 שערו \u0003תחת הדוד\u0004 שבו נתבשלו קרבנותיו (האשם וחטאת העוף), שרק בנזיר טהור כתבה תורה דין זה.","\u0003ר' מאיר אומר: הכל משלחין תחת הדוד\u0004 ובכלל זה הנזיר הטהור שגילח במדינה, וגם הנזיר הטמא, \u0003חוץ מן הטמא ש\u0004היה מגלח \u0003במדינה בלבד\u0004 שאינו משלח את שערו למקדש להישרף שם תחת קרבנו.","שנינו במשנתנו: היה \u0003נוטל שער ראש נזרו.\u0004 ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003ואחר כך,\u0004 אחרי שבישל את השלמים, \u0003נוטל את הרוטב\u0004 שבו בישלו את השלמים \u0003ונותן על שער ראש נזרו\u0004 שגולח, \u0003ומשלח תחת הדוד\u0004 \u0003של שלמים. ואם שילח\u0004 את השער \u0003תחת הדוד של חטאת ו\u0004כן של \u0003אשם יצא\u0004 ידי מצוותו. ותמהים: \u0003אשם בנזיר\u0004 \u0005[טהור\u0006\u0005]\u0006 \u0003מי איכא\u0004 \u0005[האם יש\u0006\u0005]?\u0006 והרי רק נזיר טמא מביא אשם! \u0003אמר רבא: הכי קאמר\u0004 \u0005[כך אמר\u0006\u0005]:\u0006 \u0003ואם נזיר טמא משלח תחת הדוד של אשם —\u0004 \u0003יצא.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו\u0006\u0005]\u0006 שצריך לשים רוטב הקרבן על שערו? \u0003אמר רבא: אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]\u0006 \u0003\"\u0004ונתן על האש \u0003אשר תחת זבח השלמים\"\u0004 (במדבר ו, יח), לומר כי חלק \u0003מזבחו יהא תחתיו.\u0004","ומה ששנינו בברייתא: \u0003ואם שילח תחת הדוד של חטאת —\u0004 \u0003יצא, מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר? — \u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"זבח\u0004 השלמים \u0003\"\u0004ויכול היה לומר רק \"השלמים\", אלא בא \u0003לרבות את החטאת ואשם\u0004 שאף הם נקראים \"זבח\". ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת\u0006\u0005]\u0006 כבר \u0003להאי\u0004 \u0005[את\u0006 המלה הזו\u0005]\u0006 \u0003\"זבח\"\u0004 לענין שצריך לתת \u0003מרוטב\u0004 השלמים על שערו! ומשיבים: \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב\u0006\u0005]\u0006 במפורש \u0003\"מרוטב השלמים\", מאי\u0004 \u0005[מה\u0006\u0005]\u0006 טעם השתמש בלשון \u0003\"זבח\" —\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 \u0003לרבות חטאת ואשם.\u0004","ושואלים מצד אחר: \u0003ואימא\u0004 \u0005[ואמור\u0006\u0005]\u0006 שההלכה הזו \u0003כולה לחטאת ואשם הוא דאתא\u0004 \u0005[שבאה\u0006\u0005]\u0006 ולא לענין רוטב! ומשיבים: \u0003אם כן לימא\u0004 \u0005[שיאמר\u0006\u0005]\u0006 \u0003\"שלמים וזבח\", מאי\u0004 \u0005[מה\u0006\u0005]\u0006 טעם אמר \u0003\"זבח השלמים\" —\u0004 \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שתים,\u0006 שתי הלכות\u0005].\u0006","ומביאים ברייתא נוספת בקשר לאמור במשנה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003הכל,\u0004 כל הנזירים, \u0003היו משלחין\u0004 את שערם \u0003תחת הדוד חוץ מטמא שגילח במדינה\u0004 שהוא אינו משלח \u0003מפני ששערו נקבר,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: טהורים כאן וכאן,\u0004 בין במקדש בין במדינה — \u0003היו משלחין, טמאים —\u0004 \u0003כאן וכאן לא היו משלחין. וחכמים אומרים: הכל לא היו משלחין תחת הדוד, חוץ מן טהור שבמקדש, מפני שנעשה\u0004 אז הדבר \u0003כמצותו.\u0004 ובכל אופן אחר אין זה כמצוותו האמורה לכתחילה בתורה.","\u0003היה מבשל את השלמים או שולקן\u0004 (בבישול מרובה). \u0003הכהן נוטל את הזרוע בשלה מן האיל, וחלה מצה אחת מן הסל, ורקיק מצה אחת, ונותן על כפי הנזיר, ומניפן\u0004 כפי שמפורש בתורה (במדבר ו, יט-כ), \u0003ואחר כך הותר הנזיר לשתות יין ולהטמא למתים.\u0004"],["\u0003ר' שמעון אומר: כיון שנזרק עליו\u0004 (עבור הנזיר) \u0003אחד מן הדמים\u0004 של אחד הקרבנות \u0003הותר הנזיר לשתות ביין ולהיטמא למתים,\u0004 ואין המשך סדר הדברים מעכבו עוד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 מה שנאמר בסוף פרשת הנזיר \u0003\"ואחר ישתה הנזיר יין\"\u0004 (במדבר ו, כ) — הכוונה היא \u0003אחר המעשים כולן,\u0004 כלומר, אחר הקרבת כל הקרבנות ואחר התגלחת, שהם המעשים האמורים בפרשת נזיר. אלו \u0003דברי ר' אליעזר. וחכמים אומרים: אחר מעשה יחידי,\u0004 כלומר, אחר הקרבת קרבן אחד שנעשה לצורך זה. ואפילו אם עוד לא גילח, שכן התגלחת אינה מעכבת.","ומבררים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים\u0006\u0005]?\u0006 \u0003כתיב הכא\u0004 \u0005[נאמר כאן\u0006\u0005]\u0006 \u0003\"ואחר ישתה הנזיר יין\"\u0004 \u0003וכתיב התם\u0004 \u0005[ונאמר שם\u0006\u0005]\u0006 בפסוק הקודם \u0003\"\u0004ולקח הכהן את הזרוע בשלה... ונתן על כפי הנזיר \u0003אחר התגלחו את נזרו\",\u0004 ונלמד בגזירה שווה: \u0003מה התם\u0004 \u0005[שם\u0006\u0005]\u0006 המלה \u0003\"אחר\"\u0004 משמעה אחר \u0003מעשה יחידי\u0004 שהוא גילוח, \u0003אף כאן\u0004 המלה \u0003\"אחר\"\u0004 משמעה \u0003מעשה יחידי\u0004 של הקרבת קרבן.","ושואלים: \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 שאין הנזיר מותר בשתיית יין \u0003עד דאיכא תרווייהו\u0004 \u0005[שיש\u0006 את שניהם\u0005],\u0006 גם הקרבת קרבן וגם תגלחת, שכך משמע פשוטו של הפסוק! ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך\u0006 הוא\u0005],\u0006 אם כן \u0003גזירה שוה\u0004 זו \u0003למה לי?\u0004 אלא בודאי באה ללמד שהנזיר יכול לשתות יין אפילו אחר מעשה יחידי.","\u0003אמר רב: תנופה בנזיר מעכבת\u0004 את היתר איסורי נזירותו. ושואלים: \u0003אליבא דמאן\u0004 \u0005[ל\u0006פי שיטת מי\u0005]\u0006 אמר רב הלכה זו? \u0003אילימא אליבא דרבנן\u0004 \u0005[אם תאמר לשיטת חכמים\u0006\u0005] —\u0006 אפילו \u0003תגלחת אמרי רבנן\u0004 \u0005[אומרים חכמים\u0006\u0005]\u0006 ש\u0003לא מעכבא\u0004 \u0005[מעכבת\u0006\u0005]\u0006 היתר נזירותו, \u0003תנופה\u0004 שאינה מעכבת בכל קרבן \u0003מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 לומר שאינה מעכבת בנזיר?","\u0003אלא\u0004 תאמר שהוא \u0003אליבא\u0004 \u0005[ל\u0006פי שיטת\u0005]\u0006 \u0003ר' אליעזר,\u0004 שאינו מותר אלא אחר כל המעשים — \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005]\u0006 הדבר, \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 \u0003ר' אליעזר: אחר מעשים כולם!\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]:\u0006 \u0003כיון\u0004 ש\u0003לענין כפרה\u0004 בכל הקרבנות התנופה \u0003שירי מצוה היא,\u0004 שגם אם לא הניף מתכפר לו, \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 \u0003לא תעכב\u0004 לענין היתר בנזיר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שתנופה מעכבת לענין נזיר, לדעת ר' אליעזר."],["\u0003ומי מעכבא\u0004 \u0005[והאם מעכבת\u0006\u0005]\u0006 תנופה בנזיר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"זאת תורת הנזיר\"\u0004 (במדבר ו, כא), לשון כוללת זו (\"תורת\") באה לומר שכל הנזירים שווים בדינם, \u0003בין שיש לו כפים בין שאין לו כפים,\u0004 וזה שאין לו כפיים הלא אי אפשר לו שיניף, ומשמע מכאן שאין תנופה מעכבת!","ודוחים הוכחה זו: \u0003ואלא הא דתניא\u0004 \u0005[\u0006ברייתא זו ששנויה\u0005]\u0006 באותה לשון: מה שנאמר \u0003\"זאת תורת הנזיר\"\u0004 בא לומר: \u0003בין שיש לו\u0004 לנזיר \u0003שער בין שאין לו שער, הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 תפרש ש\u0003לא מעכבא\u0004 \u0005[מעכבת\u0006\u0005]\u0006 תגלחת במי שאין לו שיער? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נזיר ממורט\u0004 (קרח לגמרי), \u0003בית שמאי אומרים: אינו צריך להעביר תער על ראשו, ובית הלל אומרים: צריך להעביר תער על ראשו.\u0004","\u0003ואמר רבינא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו צריך\" לבית שמאי\u0004 כוונתו: \u0003אינו צריך\u0004 שהרי אין לו שיער, אבל \u0003אין לו תקנה,\u0004 שאינו יכול לסיים נזירותו עד שיתגלח ממש, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 ש\u0003ל\u0004דעת \u0003בית הלל יש לו תקנה,\u0004 שיעביר תער על ראשו, לקיים את המצוה, אף שאינו מגלח. ומכאן שאף האמור בנזיר בתנופה \"בין שיש לו כפיים בין שאין לו כפיים\" יש לפרש לדעת ר' אליעזר, שתנופה מעכבת!","\u0003ו\u0004הבנה זאת, שלדעת בית שמאי צריך ואין לו תקנה, וכך דעת ר' אליעזר, \u0003היינו\u0004 \u0005[זהו\u0006\u0005]\u0006 שאמר \u0003ר' פדת.\u0004 ש\u0003אמר ר' פדת: בית שמאי ור' אליעזר אמרו דבר אחד,\u0004 כלומר, הלכו לפי עקרון אחד.","\u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 שיטת \u0003ר' אליעזר —\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 מצורע ש\u0003אין לו בהן יד ורגל\u0004 שנאמר בתורה (ויקרא יד, יד) שצריך לתת עליהן דם ושמן בזמן טהרתו — \u0003אין לו טהרה עולמית,\u0004 אלו \u0003דברי ר' אליעזר. ר' שמעון אומר: יניחנו על מקומו\u0004 של הבוהן, במקום הגדם, \u0003ויצא\u0004 בכך ידי חובתו. \u0003וחכמים אומרים: יניח על\u0004 בוהן \u0003של שמאל ויצא\u0004 ידי חובה. עד כאן הסוגיה בנוסח אחד.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[לשון אחרת אומרים אותה\u0006\u0005]\u0006 סוגיה באופן אחר, \u0003אמר רב: תנופה בנזיר מעכבת.\u0004 ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי שיטת מי\u0006\u0005]\u0006 אמר הלכה זו? \u0003אילימא אליבא\u0004 \u0005[אם תאמר לפי\u0006 שיטת\u0005]\u0006 \u0003ר' אליעזר —\u0004 \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005]\u0006 שכן היא, \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 \u0003ר' אליעזר:\u0004 אין הנזיר מותר בשתיית יין אלא \u0003אחר מעשים כולם\u0004 ובכלל זה התנופה! \u0003אלא\u0004 תאמר שרב אמר הלכה זו \u0003אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים\u0006\u0005] —\u0006 הרי זה תמוה: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר שתגלחת\u0004 שהיא כגופו ומעיקר הנזירות \u0003אמרי רבנן\u0004 \u0005[אומרים חכמים\u0006\u0005]\u0006 ש\u0003לא מעכבא\u0004 \u0005[מעכבת\u0006\u0005],\u0006 ואם כן \u0003תנופה מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 לומר שאינה מעכבת?","ושואלים: \u0003ומי\u0004 \u0005[והאם\u0006\u0005]\u0006 היא \u0003לא מעכבא\u0004 \u0005[מעכבת\u0006\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"זאת תורת הנזיר\" —\u0004 \u0003בין שיש לו כפים ובין שאין לו כפים!\u0004 ומבינים שמשמעות הדבר שבכל מקרה צריך להניף תנופה, ואין חסרון הכפיים פוטרו מן התנופה. ושואלים על הבנה זו: \u0003ואלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"זאת תורת הנזיר\" —\u0004 \u0003בין שיש לו שער ובין שאין לו שער, הכי נמי דמעכבא\u0004 \u0005[כך גם כן\u0006 תאמר שתגלחת מעכבת\u0005]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נזיר ממורט, בית שמאי אומרים: אינו צריך להעביר תער על ראשו, ובית הלל אומרים: צריך,\u0004 ומשמע אף בלא שיער — כדי לקיים העברת תער. ומכל מקום אין תגלחתו מעכבת! \u0003אמר ר' אבינא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"צריך\" לבית הלל\u0004 — כוונתו \u0003צריך, ו\u0004כיון שאינו יכול לעשות זאת — \u0003אין לו תקנה\u0004 לנזיר זה להיות מותר ביין, ואילו","\u0003ל\u0004דעת \u0003בית שמאי יש לו תקנה,\u0004 שאיננו צריך כלל לכך. \u0003ו\u0004לפי זה \u0003פליגא\u0004 \u0005[חלוקה\u0006\u0005]\u0006 שיטה זו על דעת \u0003ר' פדת,\u0004 שהרי לדעת ר' פדת שיטת בית שמאי ושיטת ר' אליעזר שוות, שמי שאינו מסוגל לעשות דבר הריהו בגדר של צריך ואין לו תקנה. ואילו ר' אבינא מבין שבית שמאי פוטרים אותו מחובה זו, ובית הלל הם האומרים שאין לו תקנה.","\u0003גילח\u0004 הנזיר \u0003על הזבח,\u0004 כלומר לאחר שהוקרבו קרבנותיו, \u0003ו\u0004לאחר מכן \u0003נמצא\u0004 הזבח \u0003פסול\u0004 מכל סיבה שהיא — \u0003תגלחתו פסולה\u0004 כמי שגילח בתוך נזירותו, \u0003וזבחיו לא עלו\u0004 (נחשבים) \u0003לו\u0004 לצאת בהם ידי חובתו. \u0003גילח על החטאת שלא לשמה\u0004 (ונפסל על ידי כך הקרבן) \u0003ואחר כך הביא קרבנותיו\u0004 האחרים \u0003לשמן —\u0004 \u0003תגלחתו פסולה, וזבחיו לא עלו לו. גילח על העולה או על השלמים שלא לשמן, ואחר כך הביא קרבנותיו\u0004 האחרים \u0003לשמן —\u0004 \u0003תגלחתו פסולה, וזבחיו לא עלו לו.\u0004","\u0003ר' שמעון אומר:\u0004 במקרה זה של המגלח על עולה או שלמים שהוקרבו שלא לשמן — \u0003אותו הזבח\u0004 שזבח שלא לשמו \u0003לא עלה לו, אבל שאר זבחים —\u0004 \u0003עלו. ו\u0004לדעת הכל \u0003אם גילח על שלשתן\u0004 ולא פירש על איזה מהם הוא מגלח, \u0003ונמצא\u0004 אפילו \u0003אחד מהן כשר —\u0004 \u0003תגלחתו כשרה, ויביא שאר זבחים\u0004 כדי להשלים את חובתו.","על דברי ר' שמעון במשנתנו \u0003אמר רב אדא בר אהבה: זאת אומרת, קסבר\u0004 \u0005[סבור\u0006\u0005]\u0006 \u0003ר' שמעון: נזיר שגילח על שלמי נדבה —\u0004 \u0003יצא,\u0004 שהרי אם גילח על שלמים שנזבחו שלא לשמם — לא עלו לו לשם חובתו, והם נחשבים כשלמי נדבה, ומכל מקום סבור ר' שמעון שתגלחתו מועילה לו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר? — ש\u0003אמר קרא\u0004 \u0005[הכתוב\u0006\u0005]:\u0006 \u0003\"ונתן על האש אשר תחת זבח השלמים\"\u0004 (ויקרא יד, יח) \u0003ולא כתב \"על שלמיו\"\u0004 משמע שאם מגלח שערו על זבח שלמים כלשהו — יצא ידי חובה."],["\u0003מי שנזרק עליו\u0004 (עבורו) על המזבח \u0003אחד מן הדמים,\u0004 של קרבנות נזירותו \u0003ונטמא\u0004 לפני שהספיק להביא את שאר קרבנותיו, \u0003ר' אליעזר אומר: סותר את הכל,\u0004 שעדיין לא יצא מנדר נזירותו. \u0003וחכמים אומרים: יביא שאר קרבנותיו ויטהר. אמרו לו\u0004 חכמים לר' אליעזר: \u0003מעשה במרים התרמודית\u0004 שהיתה נזירה \u0003שנזרק עליה אחד מן הדמים, ו\u0004לאחר מכן \u0003באו ואמרו לה על בתה שהיתה\u0004 חולה \u0003מסוכנת, והלכה ומצאה שמתה\u0004 הבת, ונטמאה לה אמה. \u0003ואמרו חכמים: תביא שאר קרבנותיה ותטהר.\u0004","\u0003קתני\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ר' אליעזר אומר סותר את הכל,\u0004 ומשמע שסותר את כל שלושים ימי נזירותו, ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003ר' אליעזר: כל\u0004 שנטמא \u0003אחר מלאת\u0004 ימי נזירותו רק \u0003שבעה\u0004 ימים \u0003סותר,\u0004 ולא יותר! \u0003אמר רב: מאי\u0004 \u0005[מה\u0006\u0005]\u0006 פירוש \u0003\"סותר\" נמי דקאמר\u0004 \u0005[גם כן שאמר\u0006\u0005]\u0006 \u0003ר' אליעזר\u0004 במשנתנו \u0003סותר קרבנותיו.\u0004 ואין כוונתו לומר שיצטרך למנות את כל ימי נזירותו מחדש, אלא שצריך להביא מחדש כל הקרבנות, ואף זה שכבר נזרק עליו דמו קודם שנטמא.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006\u0005]\u0006 לפרש את דברי ר' אליעזר, \u0003דקתני\u0004 \u0005[ש\u0006כן שנה\u0005]\u0006 בהמשך המשנה: \u0003וחכמים אומרים תביא\u0004 את \u0003שאר קרבנותיה ותטהר, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שלא נחלקו אלא בחובת הבאת הקרבנות ולא בענין הנזירות.","\u0003ומעשה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003במרים התרמודית שנזרק עליה אחד מן הדמים, ובאו והודיעוה על בתה שהיתה מסוכנת והלכה ומצאה שמתה, ואמרו חכמים: תביא שאר קרבנותיה ותטהר.\u0004 משמע שרק לגבי הקרבנות הם חלוקים ולא לגבי ימי הנזירות. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 שכן הוא.","","\u0003כהן גדול ונזיר אין מיטמאין\u0004 אפילו \u0003לקרוביהן\u0004 אם מתו. \u0003אבל מיטמאין\u0004 הם \u0003למת מצוה,\u0004 שאם מצאו אדם מישראל שאין לו קוברים — צריכים לטפל בו לקוברו, ונטמאים לו. \u0003היו\u0004 כהן גדול ונזיר \u0003מהלכין בדרך\u0004 \u0003ומצאו מת מצוה\u0004 ודי באחד מהם כדי לדאוג לקבורת המת — \u0003ר' אליעזר אומר: יטמא כהן גדול ואל יטמא נזיר. וחכמים אומרים: יטמא נזיר ואל יטמא\u0004 אפילו \u0003כהן הדיוט.\u0004 \u0003אמר להם ר' אליעזר:\u0004 מוטב ש\u0003יטמא כהן —\u0004 \u0003שאינו מביא קרבן על טומאתו, ואל יטמא נזיר —\u0004 \u0003שהוא מביא קרבן על טומאתו. אמרו לו,\u0004 יש טעם לומר להיפך: \u0003יטמא נזיר —\u0004 \u0003שאין קדושתו קדושת עולם, ואל יטמא כהן —\u0004 \u0003שקדושתו קדושת עולם.\u0004","","מתוך שהוזכרה במשנתנו מחלוקת ר' אליעזר וחכמים בכהן ונזיר, דנים במעלתם של אישים שונים. \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003כהן גדול ונזיר,\u0004 אפשר להסביר את מחלוקתם כך: \u0003האי סבר\u0004 \u0005[זה,\u0006 חכמים, סבור\u0005]:\u0006 \u0003כהן גדול עדיף\u0004 \u0005[יתר\u0006\u0005]\u0006 על הנזיר, כיון שקדושתו קדושת עולם, \u0003והאי סבר\u0004 \u0005[וזה,\u0006 ר' אליעזר, סבור\u0005]:\u0006 \u0003נזיר עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 שכן מתחייב קרבן על טומאתו.","וכן, אם היו יחד כהן \u0003משוח בשמן המשחה\u0004 ככהנים הגדולים שהיו בימי בית ראשון, שנמשחו כראוי להם,"],["\u0003ו\u0004כהן גדול \u0003מרובה בגדים\u0004 (שלובש בגדי כהן גדול ובזה הוא מתמנה לכהונתו, אבל לא נמשח בשמן המשחה) — \u0003משוח בשמן המשחה עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 והטעם הוא — ש\u0003אילו\u0004 כהן גדול \u0003משוח בשמן המשחה מביא פר הבא על כל המצות,\u0004 שאם טעה והורה היתר בעבירה חמורה (שהדיוט מביא על שגגתה חטאת) — מביא פר לחטאתו, \u0003ואילו מרובה בגדים אין מביא.\u0004","\u0003משוח ש\u0004נתמנה למלא את מקומו של הכהן הגדול שנבצר ממנו למלא את תפקידו בשל טומאה ומשנטהר הראשון וחזר לשמש בכהונה גדולה \u0003עבר\u0004 השני מכהונתו הגדולה, \u0003ומרובה בגדים —\u0004 \u0003מרובה בגדים עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 לפי ש\u0003מרובה בגדים\u0004 עדיין \u0003עביד\u0004 \u0005[עובד\u0006\u0005]\u0006 \u0003עבודה ואילו משוח שעבר לאו\u0004 \u0005[לא\u0006\u0005]\u0006 עוד \u0003בר\u0004 \u0005[בן\u0006\u0005]\u0006 \u0003עבודה הוא.\u0004","כהן משוח ש\u0003עבר מחמת קירויו\u0004 (מחמת שהוא עכשיו בעל קרי) והוא טמא לפי שעה, \u0003ו\u0004כהן ש\u0003עבר מחמת מומו —\u0004 \u0003עבר מחמת קירויו עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 ש\u0003אילו האי חזי\u0004 \u0005[זה\u0006 שעבר מחמת קריו ראוי\u0005]\u0006 \u0003לעבודה למחר, ואילו עבר מחמת מומו לא חזי\u0004 \u0005[ראוי\u0006\u0005]\u0006 עוד \u0003לעבודה\u0004 כלל.","כל אלה הם מקרים שיש להם פתרון ברור, והובאו בהקדמה לשאלות הבאות, שאין להן מענה פשוט. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003משוח מלחמה,\u0004 כהן שמתמנה לצאת עם העם למלחמה, ונמשח לשם כך בשמן המשחה (ראה דברים כ, ב), \u0003וסגן\u0004 כהן גדול, \u0003הי מינייהו עדיף\u0004 \u0005[איזה מהם יתר\u0006\u0005]?\u0006 וצדדי השאלה: האם נאמר ש\u0003משוח מלחמה עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 כיון \u0003דחזי\u0004 \u0005[שראוי\u0006\u0005]\u0006 הוא \u0003למלחמה, או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003סגן עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 \u0003דחזי\u0004 \u0005[שראוי\u0006\u0005]\u0006 \u0003לעבודה\u0004 בבית המקדש, למלא מקום הכהן הגדול?","\u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בין משוח מלחמה לסגן אלא שאם היו מהלכין בדרך ומצאו מת מצוה —\u0004 \u0003יטמא משוח מלחמה ואל יטמא הסגן.\u0004","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003משוח מלחמה קודם\u0004 במעלתו \u0003לסגן! אמר מר זוטרא:\u0004 אין זו קושיה: \u0003לענין החיותו\u0004 להוציאו מן השבי, או להצילו מסכנת מוות — \u0003משוח מלחמה עדיף\u0004 \u0005[יתר\u0006\u0005],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר — \u0003דתלו ביה\u0004 \u0005[שתלויים בו\u0006\u0005]\u0006 \u0003רבים\u0004 בזמן המלחמה, ואולם","\u0003לענין טומאה —\u0004 \u0003סגן עדיף\u0004 \u0005[יתר\u0006\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' חנינא בן אנטיגנוס אומר: למה תקנו סגן לכהן גדול —\u0004 \u0003שאם אירע בו פסול\u0004 בכהן הגדול — \u0003הרי נכנס\u0004 הסגן \u0003ומשמש תחתיו.\u0004","לגופה של ההלכה שבמשנתנו אומרים: \u0003עד כאן לא פליגי\u0004 \u0005[נחלקו\u0006\u0005]\u0006 ר' אליעזר וחכמים במשנתנו \u0003אלא בכהן גדול ונזיר כי קא אזלי בהדי הדדי\u0004 \u0005[כאשר\u0006 הם הולכים יחד\u0005]\u0006 בדרך ופגשו במת מצוה מי מהם צריך להיטמא, \u0003אבל חד חד לחודיה בר איטמויי אינון\u0004 \u0005[\u0006כל אחד ואחד לעצמו בני טומאה הם\u0005].\u0006 \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו\u0006\u0005]\u0006 שלמרות שאסורים כהן גדול ונזיר להיטמא לכל אדם ואף לקרוביהם הם, צריכים להיטמא למת מצוה?","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006\u0005]:\u0006 נאמר בכהן גדול \"ו \u0003על כל נפשת מת לא יבא\u0004 לאביו ולאמו לא יטמא\" (ויקרא כא, יא) ונברר: \u0003במה\u0004 (במי) \u0003הכתוב\u0004 \"על כל נפשות מת\" \u0003מדבר? אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003ברחוקים\u0004 שאינם קרוביו — \u0003קל וחומר הוא; ומה כהן הדיוט\u0004 שאף \u0003שהוא מיטמא ל\u0004בני משפחתו ה\u0003קרובים —\u0004 \u0003אינו מיטמא לרחוקים, כהן גדול שאינו מיטמא\u0004 אפילו \u0003לקרובים, אינו דין שאינו מיטמא לרחוקים? אלא בקרובים הכתוב מדבר\u0004 ונאסר איפוא הכהן הגדול להיטמא לכל אדם, אף לקרוביו. ואם כן, מה צורך בהמשך הדברים בפסוק הזה: \"לאביו ולאמו לא יטמא\"? אלא שכל אחד מהדברים הללו בא ללמד הלכה נוספת.","מה שנאמר \"לאביו\" בא למעט: \u0003ולאביו הוא\u0004 ש\u0003אינו מיטמא, הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003מיטמא הוא למת מצוה.\u0004"],["\u0003\"ולאמו\"\u0004 — בא \u0003ל\u0004צורך לימוד \u0003גזירה שוה, לכ\u0004 מו ששנה \u0003רבי.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003נזיר\u0004 \"לא יטמא להם במותם\" (במדבר ו, ז), לומר: דווקא \u0003במותם\u0004 של קרוביו \u0003אינו מיטמא\u0004 להם, \u0003אבל מיטמא הוא לנגעם\u0004 (אם נצטרעו) \u0003ולזיבתם. ואין לי\u0004 הלכה זו \u0003אלא בנזיר,\u0004 שדבר זה מפורש בו, \u0003בכהן גדול מנין?\u0004","\u0003אמרת: לא יאמר \"אמו\" בכהן גדול, שאין תלמוד לומר,\u0004 שאין הכתוב הזה מלמדנו דבר, ומובן שכך הדין \u0003שהרי קל וחומר הוא: ומה אם במקום שכהן הדיוט מיטמא לאחיו מאביו —\u0004 \u0003אין כהן גדול מיטמא\u0004 אפילו \u0003לאביו, מקום שאין כהן הדיוט מיטמא\u0004 אפילו \u0003לאחיו מאמו\u0004 שאינו נחשב קרוב לענין היתר טומאה — \u0003אינו דין שאין כהן גדול מיטמא לאמו\u0004 עצמה?","\u0003אם זכיתה מהדין,\u0004 כלומר, אם אכן הצלחת להוכיח את הדברים האלה לפי קל וחומר זה — אם כן \u0003מה תלמוד לומר \"אמו\" בכהן גדול?\u0004 הרי זה \u0003מופנה\u0004 (מיותר) \u0003להקיש ולדון הימנו גזירה שוה: נאמר \"אמו\" בנזיר\u0004 (במדבר ו, ז) \u0003ונאמר \"אמו\" בכהן גדול\u0004 (ויקרא כא, יא),","\u0003מה \"אמו\" האמור בנזיר\u0004 הכוונה היא — ש\u0003במותם אינו מיטמא, אבל מיטמא הוא לנגעם ולזיבתם\u0004 שהרי אין הנזיר מוזהר כלל על טומאה זו — \u0003אף \"אמו\" האמור בכהן גדול\u0004 ללמד: \u0003במותם אינו מיטמא, אבל מיטמא לנגעם ולזיבתם.\u0004","ומבררים עוד: \u0003אשכחן\u0004 \u0005[מצאנו\u0006\u0005]\u0006 איפוא את מקורו של הדין ב\u0003כהן גדול\u0004 שמיטמא למת מצוה. \u0003נזיר מנלן\u0004 \u0005[מניין לנו\u0006\u0005]\u0006 שמיטמא למת מצוה? \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בנזיר \u0003\"כל ימי הזירו לה' על נפש מת לא יבא\"\u0004 (במדבר ו, ו),","\u0003שומע אני\u0004 איסור לגבי כל הנפשות, ו\u0003אפילו נפש בהמה במשמע,\u0004 שהרי אף היא קרויה נפש, \u0003כענין שנאמר \"\u0004ו\u0003מכה נפש בהמה\"\u0004 (ויקרא כד, יח) — \u0003תלמוד לומר: \"על נפש מת לא יבא\" —\u0004 \u0003בנפש אדם הכתוב מדבר. ר' ישמעאל אומר: אינו צריך\u0004 ללימוד זה, \u0003הרי הוא אומר \"לא יבא\"\u0004 ללמד כי דווקא \u0003בנפשות המטמאות בביאה הכתוב מדבר,\u0004 כלומר באלה שבמותם מטמאים טומאת אוהל, שאם בא למקום שבו מצוי מת זה בתוכו — נטמא. ואילו בהמה מתה אינה מטמאה אלא במגע ובמשא.","ומעתה, שנאסר על הנזיר להיטמא לכל אדם, בין קרובים ובין רחוקים, מה שנוסף מיד אחר כך \u0003\"לאביו ולאמו\u0004 לא יטמא\u0003\"\u0004 (ויקרא כא, יא) בא להשמיענו דין נוסף: להם \u0003אינו מיטמא, אבל מיטמא הוא למת מצוה.\u0004","ויש מקום לשאול: ולכאורה \u0003עד שלא יאמר\u0004 הכתוב בדרך זו, \u0003יש לי בדין,\u0004 אפשר היה ללמוד זאת מעצמנו בדרך קל וחומר: \u0003ומה כהן גדול שקדושתו קדושת עולם —\u0004 \u0003מיטמא למת מצוה, נזיר שאין קדושתו קדושת עולם, אינו דין שמיטמא למת מצוה?\u0004","ויש לדחות: \u0003לא, אם אמרת בכהן גדול —\u0004 \u0003שכן אינו מביא קרבן על טומאתו\u0004 (אם נטמא), \u0003תאמר בנזיר שמביא קרבן על טומאתו. הואיל ומביא קרבן על טומאתו\u0004 שמא \u0003לא יטמא למת מצוה?\u0004 על כן \u0003תלמוד לומר: \"לאביו ולאמו לא יטמא\" —\u0004 \u0003אבל מיטמא\u0004 הוא \u0003למת מצוה.\u0004","\u0003או\u0004 שמא תלמד מכאן באופן אחר: \u0003אינו מיטמא לאביו ולאמו —\u0004 \u0003אבל יטמא לשאר מתים!\u0004 ויש לדחות: \u0003אמרת קל וחומר\u0004 הוא: \u0003ומה כהן הדיוט שמיטמא לקרובין —\u0004 \u0003אינו מיטמא לשאר מתים\u0004 שאינם קרוביו (ראה ויקרא כא, א-ב), \u0003נזיר שאינו מיטמא לקרובין אינו דין שלא יטמא לשאר מתים?\u0004"],["\u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003מה תלמוד לומר \"לאביו ולאמו\"\u0004 (במדבר ו, ז) — להדגיש: \u0003לאביו ולאמו הוא\u0004 ש\u0003לא מיטמא, אבל מיטמא הוא למת מצוה.\u0004","ואפשר לשאול על הצורך בלימוד זה: \u0003עד\u0004 ש\u0003לא יאמר\u0004 דבר זה מדיוק הכתוב, \u0003יש לי\u0004 בידי ללמוד זאת לכאורה \u0003בדין\u0004 (מסברה); \u0003נאמרו כללות,\u0004 איסור כללי שלא להיטמא למת (\"ועל כל נפשות מת לא יבוא\". ויקרא כא, יא) \u0003בכהן גדול, ונאמרו כללות\u0004 כאלה גם \u0003בנזיר\u0004 (\"על נפש מת לא יבוא\". במדבר ו, ו), \u0003מה כללות האמורות בכהן גדול\u0004 למדים מהן כי \u0003לאביו אינו מיטמא אבל מיטמא למת מצוה, אף כללות האמורות בנזיר —\u0004 \u0003לאביו אינו מיטמא אבל מיטמא למת מצוה,\u0004 ונמצא שאין צורך בלימוד מ\"לאביו ולאמו\".","ואולם אפשר לדחות: \u0003או כלך לדרך זו\u0004 (לך בשיטה אחרת): \u0003נאמרו כללות\u0004 לאיסור טומאת המת \u0003בכהן הדיוט\u0004 (ככתוב \"לנפש לא יטמא בעמיו\". ויקרא כא, א) \u0003ונאמרו כללות בנזיר, מה כללות האמורות בכהן הדיוט\u0004 — בכל זאת \u0003מיטמא לאביו\u0004 (כמפורש ויקרא כא, ב), \u0003אף כללות האמורות בנזיר מיטמא לאביו.\u0004","לכן לא ניתן ללמוד מן הכלל, אלא כפי שדייקנו: \u0003תלמוד לומר\u0004 בנזיר \u0003\"לאביו ולאמו לא יטמא\", הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003למת מצוה מיטמא.\u0004 על הוכחה אחרונה זו שואלים: \u0003הא מיבעי ליה\u0004 \u0005[\u0006הרי פסוק זה נצרך לו\u0005]\u0006 לעצם הדין, \u0003לומר שאין מיטמא לאביו\u0004 (שלא ככהן הדיוט), וכיצד למד מכאן שמיטמא למת מצוה?","\u0003אלא\u0004 כך צריך לומר: ייתור המלה \u0003\"לאביו\"\u0004 בא \u0003לומר שאין מיטמא לאביו,\u0004 וכל שכן לשאר קרוביו. ואילו ייתור המלה \u0003\"לאחיו\"\u0004 בא לומר: לאחיו \u0003אינו מיטמא, הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003למת מצוה מיטמא. \"ולאמו\" —\u0004 \u0003לגזרה שוה, לכ\u0004 פי שדרש \u0003רבי\u0004 שמיטמא לשאר טומאות שאינן טומאת מת.","\u0003\"ולאחותו\"\u0004 בא ללמד עוד הלכה אחרת, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 הכתוב בנזיר \u0003\"לאחותו\" מה תלמוד לומר?\u0004 שהרי פרט זה לכאורה מיותר, שכבר למדנו כל הלכות טומאת נזיר משאר הפרטים!","אלא בא ללמד: \u0003הרי שהלך\u0004 אדם \u0003לשחוט את פסחו ו\u0004כן \u0003למול את בנו\u0004 שהן מצוות עשה חמורות שיש חיוב כרת על ביטולן, \u0003ושמע שמת לו מת\u0004 אחד מקרוביו — \u0003יכול יטמא\u0004 למתו וייבטל מן המצוה — \u0003אמרת: לא יטמא,\u0004 שאינו רשאי לבטל מצוה חמורה זו, אף מפני טומאת קרובו.","\u0003יכול\u0004 אף \u0003לא יטמא למת מצוה —\u0004 \u0003תלמוד לומר: \"לאחותו\",\u0004 הרי זה בא להדגיש: דווקא \u0003לאחותו\u0004 או לשאר קרוביו \u0003הוא\u0004 ש\u0003אינו מיטמא\u0004 הנזיר אף לצורך מצוה חשובה, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003למת מצוה — הריהו\u0004 \u0003מיטמא.\u0004","\u0003ר' עקיבא אומר\u0004 שיש לדרוש פסוק זה בנזיר באופן אחר: מן האמור \"על נפש מת לא יבוא\" נלמד כך: \u0003\"נפשות\" —\u0004 \u0003אלו הרחוקין, \"מת\" —\u0004 \u0003אלו הקרובין,\u0004 ובא הפסוק הבא להדגיש: \u0003\"לאביו ולאמו\" אינו מיטמא, אבל מיטמא הוא למת מצוה.\u0004","ולמה נאמר \u0003\"לאחיו\"\u0004 הרי זה להדגשה נוספת: \u0003שאם היה כהן גדול והוא נזיר —\u0004 \u0003לאחיו אינו מיטמא, אבל מיטמא הוא למת מצוה. \"לאחותו\" —\u0004 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה הולך לשחוט את פסחו ולמול את בנו כו',\u0004 כלומר, אפילו בזמן שהוא הולך לעשות מצוה חשובה זו ונזדמן לפניו מת מצוה — מת מצוה קודם.","ושואלים: \u0003ולר' עקיבא, גזירה שוה\u0004 של \u0003רבי,\u0004 מ\"ולאמו\", שמותר הכהן הגדול, כפי שמותר הנזיר, להיטמא לשאר טומאות (שאינן טומאת מת) של קרוביו, \u0003מנליה\u0004 \u0005[מניין לו\u0006\u0005]\u0006 מניין הוא למד הלכה זו?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך: כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 \u0003אם היה\u0004 אותו אדם גם \u0003כהן גדול ו\u0004גם \u0003נזיר, לאחיו אינו מיטמא, אבל מיטמא הוא למת מצוה,\u0004 אם כן יש לנו לומר \u0003מה לי כהן גדול לחודיה\u0004 \u0005[לבדו\u0006\u0005]\u0006 \u0003מה לי נזיר וכהן גדול.\u0004 ומאחר שגילה הכתוב בנזיר שהוא רשאי להיטמא לנגעי קרוביו (\"לא יטמא להם במותם\") — הוא הדין כשהיה כהן גדול ונזיר.","ושואלים: \u0003ול\u0004דעת \u0003ר' ישמעאל, כהן גדול והוא נזיר מנליה\u0004 \u0005[מניין לו\u0006\u0005]\u0006 שמיטמא למת מצוה? ומשיבים: \u0003כיון דשרא רחמנא חד לאו\u0004 \u0005[שהתירה התורה לאו אחד\u0006\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003מת מצוה\u0004 בין בנזיר ובין בכהן גדול — \u0003מה לי חד לאו\u0004 \u0005[לאו אחד\u0006\u0005],\u0006 \u0003מה לי תרין\u0004 \u0005[שני\u0006\u0005]\u0006 \u0003לאוין,\u0004 שאם התירה התורה איסור טומאה לגבי מת מצוה, אין הבדל אם היה זה איסור אחד בפני עצמו או שניהם יחד.","\u0003\"אחותו\" למה לי? סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר\u0006\u0005]\u0006 \u0003כי שרא רחמנא\u0004 \u0005[כאשר התירה התורה\u0006\u0005]\u0006 להיטמא \u0003למת מצוה\u0004 הרי זה ב\u0003נזיר וכהן\u0004 — ש\u0003איסור לאוי\u0004 \u0005[לאוין\u0006\u0005]\u0006 \u0003הוא,\u0004 שאין בהם אלא מצוות לא תעשה להיטמא. \u0003אבל מילה ופסח\u0004 שיש בביטולם עונש \u0003כרת, לא יטמא למת מצוה —\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שבכל זאת מיטמא."],["\u0003ולר' עקיבא, מכדי\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003לא שנא\u0004 \u0005[שונה\u0006\u0005]\u0006 בעיניו הדין אם היה הוא \u0003כהן גדול לחודיה\u0004 \u0005[לבדו\u0006\u0005]\u0006 \u0003ולא שנא\u0004 \u0005[שונה\u0006\u0005]\u0006 אם היה \u0003כהן גדול והוא\u0004 גם \u0003נזיר,\u0004 הלוא ההלכה שמותר לו להיטמא למת מצוה \u0003נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]\u0006 \u0003מ\"לאחיו\"\u0004 האמור בנזיר (במדבר ו, ז), אם כן מה שנכתב \u0003\"לאביו ולאמו\" למה לי?\u0004 הרי די באיסור הכללי להיטמא לכל מת!","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים\u0006 שניהם\u0005]\u0006 להיכתב: \u0003דאי כתב\u0004 \u0005[שאם היה כותב\u0006\u0005]\u0006 רק \u0003\"\u0004ל\u0003אביו\" הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003היינו טעמא\u0004 \u0005[זה הטעם\u0006\u0005]\u0006 ש\u0003לא מיטמא ליה\u0004 \u0005[לו\u0006\u0005] —\u0006 \u0003משום\u0004 ש\u0003חזקה בעלמא\u0004 \u0005[בלבד\u0006\u0005]\u0006 \u0003הוא,\u0004 שהרי לעולם אין הוכחה ודאית שאכן אדם זה הוא אביו, אלא סומכים על החזקה שכיון שמוחזק שהוא אביו — מן הסתם אביו הוא. \u0003אבל אמו דידעין דילדתיה\u0004 \u0005[ש\u0006אנו יודעים שילדה אותו\u0005] —\u0006 \u0003ליטמא\u0004 \u0005[יטמא\u0006\u0005]\u0006 \u0003לה,\u0004 שהרי לגבי אמהות יכולה להיות עדות גמורה, ולכן היה צריך לכתוב \"אמו\".","ולהיפך: \u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה כותבת התורה\u0005]\u0006 \"ל \u0003אמו\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 דווקא \u0003אמו לא ליטמא\u0004 \u0005[יטמא\u0006\u0005]\u0006 \u0003לה —\u0004 משום \u0003דלאו אזיל\u0004 \u0005[שאין הולך\u0006\u0005]\u0006 \u0003זרעה בתרה\u0004 \u0005[אחריה\u0006\u0005],\u0006 שאין אדם מתייחס אחר אמו אלא אחר אביו. \u0003אבל אביו, כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 ודייק מן הכתוב \u0003\"למשפחתם לבית אבתם\"\u0004 (במדבר א, ב) שייחוס המשפחה נקבע לפי האב, \u0003אימא ליטמא ליה\u0004 \u0005[אמור שייטמא לו\u0006\u0005] —\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שגם לאביו אינו מיטמא.","ושואלים: ולשיטת ר' עקיבא, \u0003\"ועל כל נפשת מת לא יבא\"\u0004 (ויקרא כא, יא) האמור בכהן גדול \u0003למה לי?\u0004"],["\u0003\"על כל\" —\u0004 \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003רחוקים,\u0004 שלא ייטמא להם, \u0003\"מת\" —\u0004 \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003קרובים, \"נפשת\" —\u0004 \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003רביעית דם שיצא משני מתים\u0004 (\"נפשות\") שגם הוא \u0003מטמא באהל, שנאמר: \"\u0004ו\u0003על כל נפשת מת לא יבא\"\u0004 (במדבר כא יא) — אפילו דם של שתי נפשות מצטרף יחד לשיעור טומאה.","\u0003על אלו טומאות הנזיר מגלח\u0004 אם נטמא בהן: \u0003על המת, ועל כזית מן המת, ועל כזית נצל\u0004 (ליחה היוצאת מן המת), \u0003ועל מלא תרווד\u0004 (כף גדולה) של \u0003רקב\u0004 מן המת. \u0003על השדרה, ועל הגולגולת, ועל אבר מן המת\u0004 \u0003ועל אבר מן החי שיש עליו\u0004 על אחד מהם \u0003בשר כראוי, ועל חצי קב עצמות\u0004 מת, \u0003ועל חצי לוג דם.\u0004","\u0003ו\u0004מגלח הנזיר בכל אלו \u0003על מגען ועל משאן ועל אהילן\u0004 אם מאהיל עליהם, או נכנס לאוהל שהם מצויים בו. \u0003ועל עצם\u0004 מן המת שגודלה \u0003כשעורה\u0004 מיטמא \u0003על מגעו ועל משאו,\u0004 אבל אין לו טומאת אוהל.","\u0003על\u0004 כל \u0003אלו הנזיר מגלח, ומזה ב\u0004יום ה\u0003שלישי וב\u0004יום ה\u0003שביעי\u0004 להיטהר מטומאת המת, \u0003וסותר את\u0004 כל הימים \u0003הקודמין\u0004 שכבר מנה לנזירותו, \u0003ואינו מתחיל למנות\u0004 לנזירות חדשה \u0003אלא עד שיטהר ומביא את קרבנותיו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003אחר פטירתו של ר' מאיר אמר להן ר' יהודה לתלמידיו: אל יכנסו תלמידי רבי מאיר לכאן\u0004 לבית המדרש, \u0003מפני שקנתרנין\u0004 (מרגיזים) \u0003הן, ולא ללמוד תורה הן באין אלא לקפחני\u0004 (להציק לי, לנצח אותי) \u0003בהלכות הן באין.\u0004 בכל זאת \u0003דחק סומכוס\u0004 תלמידו של ר' מאיר \u0003ונכנס.\u0004","וכאשר עסקו באותו ענין \u0003אמר להם: כך שנה לי\u0004 רבי, \u0003ר' מאיר\u0004 (כפי שהוא במשנתנו): \u0003על אלו טומאות הנזיר מגלח: על המת ועל כזית מן המת. כעס ר' יהודה ואמר להן, לא כך אמרתי לכם: אל יכנסו תלמידי ר' מאיר לכאן מפני שקנתרנין הן?\u0004 שהרי מה שאמר בשם ר' מאיר \"על המת\" אין לו צורך לאומרו, שהרי אם \u0003על כזית מן המת מגלח —\u0004 \u0003על המת\u0004 כולו \u0003לא כל שכן?!\u0004"]]};
